/** All translations for zizhitongjian ch.040 — Garrett M. Petersen (2026), Composer 2.5 */
export const entries = [
  { zh: "【漢紀三十二】起旃蒙作噩，盡柔兆閹茂，凡二年。", literal: "【Han Records 32】 From Zhanmeng Zuoe through Rouzhao Yanmao—in all, two years.", idiomatic: "【Han Records 32】 From the first year of the Zhanmeng cycle through the last year of the Rouzhao cycle—two years in all." },
  { zh: "世祖光武皇帝上之上", literal: "Founding Emperor Guangwu, Upper Part 1, First Section.", idiomatic: "The Founding Emperor Guangwu — Upper Part 1, First Section." },
  { zh: "1春，正月，方望與安陵人弓林共立前定安公嬰為天子，聚黨數千人，居臨涇。", literal: "1. In spring, the first month, Fang Wang together with Gong Lin of Anling jointly set up the former Duke of Ding'an, Ying, as Son of Heaven; they gathered a faction of several thousand men and dwelt at Linjing.", idiomatic: "1. In spring, in the first month, Fang Wang and Gong Lin of Anling jointly enthroned the former Duke of Ding'an, Liu Ying, as emperor; they gathered several thousand followers and encamped at Linjing." },
  { zh: "更始遣丞相松等擊破，皆斬之。", literal: "Gengshi sent Chancellor Song and others to defeat and break them; all were beheaded.", idiomatic: "The Gengshi Emperor sent Chancellor Song and others to rout them; all were beheaded." },
  { zh: "2鄧禹至箕關，擊破河東都尉，進圍安邑。", literal: "2. Deng Yu reached Jiguan Pass, defeated and broke the Hedong commandant, and advanced to besiege Anyi.", idiomatic: "2. Deng Yu reached Jiguan Pass, routed the Hedong commandant, and advanced to besiege Anyi." },
  { zh: "3赤眉二部俱會弘農。", literal: "3. The two divisions of the Red Eyebrows both assembled at Hongnong.", idiomatic: "3. The two divisions of the Red Eyebrows united at Hongnong." },
  { zh: "更始遣討難將軍蘇茂拒之；", literal: "Gengshi sent the Pacify-Difficulty General Su Mao to resist them;", idiomatic: "The Gengshi Emperor sent Pacify-Difficulty General Su Mao to resist them;" },
  { zh: "茂軍大敗。", literal: "Mao's army was utterly defeated.", idiomatic: "Su Mao's army was routed." },
  { zh: "赤眉眾遂大集，乃分萬人為一營，凡三十營。", literal: "The Red Eyebrow host thereupon gathered in great numbers; they then divided ten thousand men to a camp—in all thirty camps.", idiomatic: "The Red Eyebrows then massed in force, organizing ten thousand men per camp—thirty camps in all." },
  { zh: "三月，更始遣丞相松與赤眉戰於蓩鄉，松等大敗，死者三萬餘人。", literal: "In the third month, Gengshi sent Chancellor Song to fight the Red Eyebrows at Maoxiang; Song and the others were utterly defeated, and more than thirty thousand died.", idiomatic: "In the third month the Gengshi Emperor sent Chancellor Song against the Red Eyebrows at Maoxiang; Song was routed and more than thirty thousand men were killed." },
  { zh: "赤眉遂轉北至湖。", literal: "The Red Eyebrows thereupon turned and marched north to Hu.", idiomatic: "The Red Eyebrows then turned north toward Hu." },
  { zh: "4蜀郡功曹李熊說公孫述宜稱天子。", literal: "4. Li Xiong, merit-clerk of Shu Commandery, urged Gongsun Shu that he ought to style himself Son of Heaven.", idiomatic: "4. Li Xiong, merit-clerk of Shu Commandery, urged Gongsun Shu to declare himself emperor." },
  { zh: "夏，四月，述即帝位，號成家，改元龍興；", literal: "In summer, the fourth month, Shu took the emperor's position, styled his state Chengjia, and changed the era name to Longxing;", idiomatic: "In summer, in the fourth month, Gongsun Shu took the throne, named his state Chengjia, and adopted the era name Longxing;" },
  { zh: "〔以〕李熊為大司徒<ref>〔以〕李熊為大司徒章校「十二行本『李』上有『以』字；", literal: "〔and〕 made Li Xiong Grand Minister of Education<ref>〔And〕 made Li Xiong Grand Minister of Education—Zhang's collation: \"In the twelve-line edition there is the character 'with' above 'Li';\"", idiomatic: "〔and〕 appointed Li Xiong Grand Minister of Education<ref>〔And〕 appointed Li Xiong Grand Minister of Education—Zhang's collation: \"In the twelve-line edition 'with' appears above 'Li';\"" },
  { zh: "乙十一行本同；", literal: "the Yi eleven-line edition agrees;", idiomatic: "the Yi eleven-line edition agrees;" },
  { zh: "孔本同；", literal: "the Kong edition agrees;", idiomatic: "the Kong edition agrees;" },
  { zh: "張校同。", literal: "Zhang's collation agrees.", idiomatic: "Zhang's collation agrees." },
  { zh: "」《後漢書．公孫述傳》同，據補。", literal: "\" The \"Biography of Gongsun Shu\" in the Book of the Later Han agrees; supplemented accordingly.", idiomatic: "\" The \"Biography of Gongsun Shu\" in the Book of the Later Han agrees; supplemented accordingly." },
  { zh: "</ref>，述弟光為大司馬，恢為大司空。", literal: "</ref>, Shu's younger brother Guang was made Grand Marshal and Hui Grand Minister of Works.", idiomatic: "</ref> His younger brother Guang became Grand Marshal and Hui Grand Minister of Works." },
  { zh: "越巂任貴據郡降述。", literal: "Ren Gui of Yuexi held the commandery and surrendered to Shu.", idiomatic: "Ren Gui of Yuexi held the commandery and submitted to Gongsun Shu." },
  { zh: "5蕭王北擊尤來、大槍、五幡於元氏，追至北平，連破之；", literal: "5. The Prince of Xiao marched north to attack Youlai, Daqiang, and Wufan at Yuanshi, pursued them to Beiping, and defeated them repeatedly;", idiomatic: "5. The Prince of Xiao marched north against Youlai, Daqiang, and Wufan at Yuanshi, pursued them to Beiping, and defeated them in succession;" },
  { zh: "又戰於順水北，乘勝輕進，反為所敗。", literal: "they fought again north of the Shun River; riding victory he pressed lightly forward and was in turn defeated by them.", idiomatic: "he fought again north of the Shun River; pressing his advantage too boldly, he was routed in turn." },
  { zh: "王自投高岸，〔遇〕突騎王豐下馬授王<ref>〔遇〕突騎王豐下馬授王章校「十二行本『突』上有『遇』字；", literal: "the prince threw himself onto a high bank; 〔encountering〕 the shock cavalryman Wang Feng, who dismounted and gave his horse to the prince<ref>〔Encountering〕 the shock cavalryman Wang Feng, who dismounted and gave his horse to the prince—Zhang's collation: \"In the twelve-line edition there is the character 'encounter' above 'shock';\"", idiomatic: "the prince leaped onto a high bank; 〔there〕 the shock cavalryman Wang Feng dismounted and gave him his horse<ref>〔There〕 the shock cavalryman Wang Feng dismounted and gave him his horse—Zhang's collation: \"In the twelve-line edition 'encounter' appears above 'shock';\"" },
  { zh: "乙十一行本同；", literal: "the Yi eleven-line edition agrees;", idiomatic: "the Yi eleven-line edition agrees;" },
  { zh: "孔本同；", literal: "the Kong edition agrees;", idiomatic: "the Kong edition agrees;" },
  { zh: "張校同；", literal: "Zhang's collation agrees;", idiomatic: "Zhang's collation agrees;" },
  { zh: "退齋校同。", literal: "Tui Zhai's collation agrees.", idiomatic: "Tui Zhai's collation agrees." },
  { zh: "」《後漢書．光武帝紀》同，據補。", literal: "\" The \"Annals of Emperor Guangwu\" in the Book of the Later Han agrees; supplemented accordingly.", idiomatic: "\" The \"Annals of Emperor Guangwu\" in the Book of the Later Han agrees; supplemented accordingly." },
  { zh: "</ref>，王僅而得免。", literal: "</ref> The prince barely escaped.", idiomatic: "</ref> The prince barely escaped with his life." },
  { zh: "散兵歸保范陽。", literal: "Scattered troops returned to hold Fanyang.", idiomatic: "The scattered troops fell back to defend Fanyang." },
  { zh: "軍中不見王，或云已〔歿〕(", literal: "Within the army the prince was not seen; some said he had already 〔perished〕(", idiomatic: "The prince could not be found in camp; some said he had already 〔perished〕(" },
  { zh: "殺)", literal: "been killed)", idiomatic: "been killed)" },
  { zh: "<ref>或云已〔歿〕(", literal: "<ref>Some said he had already 〔perished〕(", idiomatic: "<ref>Some said he had already 〔perished〕(" },
  { zh: "殺)", literal: "been killed)", idiomatic: "been killed)" },
  { zh: "章校「十二行本『殺』作『歿』；", literal: "Zhang's collation: \"In the twelve-line edition 'killed' reads 'perished';\"", idiomatic: "Zhang's collation: \"In the twelve-line edition 'killed' reads 'perished';\"" },
  { zh: "乙十一行本同；", literal: "the Yi eleven-line edition agrees;", idiomatic: "the Yi eleven-line edition agrees;" },
  { zh: "孔本同。", literal: "the Kong edition agrees.", idiomatic: "the Kong edition agrees." },
  { zh: "」《後漢書．光武帝紀》同，據改。", literal: "\" The \"Annals of Emperor Guangwu\" in the Book of the Later Han agrees; amended accordingly.", idiomatic: "\" The \"Annals of Emperor Guangwu\" in the Book of the Later Han agrees; amended accordingly." },
  { zh: "</ref>，諸將不知所為，吳漢曰：「卿曹努力！", literal: "</ref> The generals did not know what to do; Wu Han said: \"You gentlemen, exert yourselves!", idiomatic: "</ref> The generals were at a loss. Wu Han said, \"Gentlemen, do your utmost!" },
  { zh: "王兄子在南陽，何憂無主！", literal: "The prince's elder brother's son is in Nanyang—why worry that there is no lord!\"", idiomatic: "The prince's nephew sits in Nanyang—why fear we lack a leader?\"" },
  { zh: "」眾恐懼，數日乃定。", literal: "\" The host was fearful; only after several days did they settle.", idiomatic: "\" The army was terrified; several days passed before order returned." },
  { zh: "賊雖戰勝，而憚王威名，夜，遂引去。", literal: "Though the bandits had won the battle, they feared the prince's awesomeness and name; at night they thereupon withdrew.", idiomatic: "Though the rebels had won, they feared the prince's renown; that night they withdrew." },
  { zh: "大軍復進至安次<ref>大軍復進至安次章校「十二行本『進』作『追』；", literal: "The great army again advanced to Anci<ref>The great army again advanced to Anci—Zhang's collation: \"In the twelve-line edition 'advance' reads 'pursue';\"", idiomatic: "The main force advanced again to Anci<ref>The main force advanced again to Anci—Zhang's collation: \"In the twelve-line edition 'advance' reads 'pursue';\"" },
  { zh: "乙十一行本同；", literal: "the Yi eleven-line edition agrees;", idiomatic: "the Yi eleven-line edition agrees;" },
  { zh: "孔本同；", literal: "the Kong edition agrees;", idiomatic: "the Kong edition agrees;" },
  { zh: "張校同。", literal: "Zhang's collation agrees.", idiomatic: "Zhang's collation agrees." },
  { zh: "」《後漢書．光武帝紀》此作「進」，今不改。", literal: "\" Here the \"Annals of Emperor Guangwu\" reads \"advance\"; it is not changed now.", idiomatic: "\" The \"Annals of Emperor Guangwu\" reads \"advance\" here; the text is left unchanged." },
  { zh: "</ref>，連戰，破之。", literal: "</ref> They fought repeatedly and broke the enemy.", idiomatic: "</ref> They fought repeatedly and routed the enemy." },
  { zh: "賊退入漁陽，所過虜掠。", literal: "The bandits retreated into Yuyang and plundered wherever they passed.", idiomatic: "The rebels fell back into Yuyang, plundering as they went." },
  { zh: "強弩將軍陳俊言於王曰：「賊無輜重，宜令輕騎出賊前，使百姓各自堅壁以絕其食，可不戰而殄也。", literal: "The Powerful Crossbow General Chen Jun said to the prince: \"The bandits have no baggage train; it is fitting to send light cavalry out ahead of them and make the hundred surnames each strengthen their walls to cut off their food—they can be exterminated without fighting.\"", idiomatic: "Powerful Crossbow General Chen Jun told the prince, \"The rebels carry no baggage. Send light cavalry ahead of them and order the people to fortify their walls and cut off their supplies—you can destroy them without a battle.\"" },
  { zh: "」王然之，遣俊將輕騎馳出賊前，視人保壁堅完者，敕令固守；", literal: "\" The prince approved, sent Jun to lead light cavalry galloping out ahead of the bandits, and wherever he saw people whose fortified walls were firm and complete, he ordered them to hold fast;", idiomatic: "\" The prince agreed and sent Chen Jun with light cavalry racing ahead of the enemy; wherever he found villages with strong defenses, he ordered them to hold firm;" },
  { zh: "放散在野者，因掠取之。", literal: "those scattered in the open fields he released to be seized and taken.", idiomatic: "whatever grain lay in the open fields he seized for the army." },
  { zh: "賊至，無所得，遂散敗。", literal: "When the bandits arrived they obtained nothing and thereupon scattered in defeat.", idiomatic: "When the rebels arrived they found nothing and broke apart in defeat." },
  { zh: "王謂俊曰：「困此虜者，將軍策也。", literal: "The prince said to Jun: \"To have trapped these captives—this was the general's stratagem.\"", idiomatic: "The prince told Chen Jun, \"To have trapped these foes was your stratagem.\"" },
  { zh: "6馮異遺李軼書，為陳禍福，勸令歸附蕭王；", literal: "6. Feng Yi sent a letter to Li Yi, setting forth fortune and misfortune and urging him to submit to the Prince of Xiao;", idiomatic: "6. Feng Yi wrote to Li Yi, laying out fortune and ruin and urging him to submit to the Prince of Xiao;" },
  { zh: "軼知長安已危，而以伯升之死，心不自安，乃報書曰：「軼本與蕭王首謀造漢，今軼守洛陽，將軍鎮孟津，俱據機軸，千載一會，思成斷金。", literal: "Yi knew Chang'an was already in peril, yet because of Bo Sheng's death his heart was not at ease; he thereupon replied: \"Yi originally with the Prince of Xiao first plotted to create Han; now Yi holds Luoyang while the general garrisons Mengjin—we both hold the pivot of the realm, a meeting once in a thousand years; I think to forge metal that will not break.\"", idiomatic: "Li Yi knew Chang'an was doomed, yet Liu Xiu's brother's death left him uneasy. He replied, \"I first plotted with the Prince of Xiao to restore Han. Now I hold Luoyang while you garrison Mengjin—we both grip the empire's pivot. Such a meeting comes once in a thousand years; let us forge a bond that will not break.\"" },
  { zh: "唯深達蕭王，願進愚策以佐國安民。", literal: "Only deeply convey this to the Prince of Xiao; I wish to advance foolish counsel to aid the state and settle the people.\"", idiomatic: "Convey my words faithfully to the prince; I wish to offer humble counsel to aid the realm and comfort the people.\"" },
  { zh: "」軼自通書之後，不復與異爭鋒，故異得北攻天井關，拔上黨兩城，又南下河南成皋以東十三縣，降者十餘萬。", literal: "\" From the time Yi opened correspondence he no longer contended with Yi in arms; therefore Yi was able to attack north at Tianjing Pass, take two cities of Shangdang, and again march south through thirteen counties east of Chenggao in Henan—those who submitted numbered more than a hundred thousand.", idiomatic: "\" After this exchange Li Yi ceased fighting Feng Yi, who marched north against Tianjing Pass, took two cities in Shangdang, then swept south through thirteen counties east of Chenggao in Henan—more than a hundred thousand submitted." },
  { zh: "武勃將萬餘人攻諸畔者，異與戰於士鄉下，大破，斬勃；", literal: "Wu Bo led more than ten thousand men to attack those who had rebelled; Yi fought him below Shixiang, routed him utterly, and beheaded Bo;", idiomatic: "Wu Bo led more than ten thousand men against the defectors; Feng Yi met him at Shixiang, routed his force, and beheaded Wu Bo;" },
  { zh: "軼閉門不救。", literal: "Yi shut his gates and did not rescue him.", idiomatic: "Li Yi shut his gates and would not rescue him." },
  { zh: "異見其信效，具以白王。", literal: "Yi saw his trustworthiness and effectiveness and reported it all to the prince.", idiomatic: "Feng Yi, seeing this proof of good faith, reported everything to the prince." },
  { zh: "王報異曰：「季文多詐，人不能得其要領。", literal: "The prince replied to Yi: \"Jiwen is full of deceit—men cannot grasp his essential point.\"", idiomatic: "The prince replied, \"Jiwen is treacherous; no one can read his true intent.\"" },
  { zh: "今移其書告守、尉當警備者。", literal: "Now circulate his letter and inform every defender and commandant who ought to be on guard.\"", idiomatic: "Now circulate his letter and warn every garrison commander to stand alert.\"" },
  { zh: "」眾皆怪王宣露軼書；", literal: "\" All wondered at the prince's revealing Yi's letter;", idiomatic: "\" All marveled that the prince had exposed Li Yi's letter;" },
  { zh: "朱鮪聞之，使人刺殺軼，由是城中乖離，多有降者。", literal: "Zhu Wei heard of it and sent men to assassinate Yi; from this the city fell into division and many submitted.", idiomatic: "Zhu Wei heard of it and had Li Yi assassinated; the city split apart and many defected." },
  { zh: "朱鮪聞王北征而河內孤，乃遣其將蘇茂、賈彊將兵三萬餘人渡鞏河，攻溫；", literal: "Zhu Wei, hearing the prince had marched north while Henei stood isolated, thereupon sent his generals Su Mao and Jia Qiang leading more than thirty thousand troops across the Gong River to attack Wen;", idiomatic: "Zhu Wei, learning the prince had marched north leaving Henei exposed, sent Su Mao and Jia Qiang with more than thirty thousand men across the Gong River to attack Wen;" },
  { zh: "鮪自將數萬人攻平陰以綴異。", literal: "Wei himself led several tens of thousands to attack Pingyin in order to pin Yi.", idiomatic: "Zhu Wei himself led tens of thousands against Pingyin to tie down Feng Yi." },
  { zh: "檄書至河內，寇恂即勒軍馳出，並移告屬縣，發兵會溫下。", literal: "When the dispatch reached Henei, Kou Xun immediately mustered his army and galloped out, and at the same time sent notice to subordinate counties to raise troops and assemble below Wen.", idiomatic: "When the dispatch reached Henei, Kou Xun mustered his troops at once, notified the subordinate counties, and raced to Wen with every man he could raise." },
  { zh: "軍吏皆諫曰：「今洛陽兵渡河，前後不絕。", literal: "The army officers all remonstrated, saying: \"Now Luoyang's troops are crossing the river, front and rear without break.\"", idiomatic: "His officers all urged caution: \"Luoyang's troops are crossing the river in an unbroken stream.\"" },
  { zh: "宜待眾軍畢集，乃可出也。", literal: "\"It is fitting to wait until all armies are fully gathered—only then may we go out.\"", idiomatic: "\"We should wait until every force has assembled before we march out.\"" },
  { zh: "」恂曰：「溫，郡之籓蔽，失溫則郡不可守。", literal: "\" Xun said: \"Wen is the commandery's outer shield; lose Wen and the commandery cannot be held.\"", idiomatic: "\" Kou Xun said, \"Wen is this commandery's shield; lose Wen and Henei cannot be held.\"" },
  { zh: "」遂馳赴之。", literal: "\" He thereupon galloped to the rescue.", idiomatic: "\" He raced to its relief." },
  { zh: "旦日，合戰，而馮異遣救及諸縣兵適至，恂令士卒乘城鼓噪大呼，言曰：「劉公兵到！", literal: "At dawn they joined battle; Feng Yi had sent relief and the county troops just arrived; Xun ordered his soldiers to mount the walls, beat drums, shout loudly, and cry: \"Lord Liu's troops have arrived!\"", idiomatic: "At dawn the armies clashed; Feng Yi's relief force and the county levies arrived just then. Kou Xun ordered his men onto the walls to drum and shout, \"Lord Liu's army is here!\"" },
  { zh: "」蘇茂軍聞之，陳動。", literal: "\" Su Mao's army heard it and their formation wavered.", idiomatic: "\" Su Mao's ranks wavered at the cry." },
  { zh: "恂因奔擊，大破之。", literal: "Xun thereupon charged and struck; he routed them utterly.", idiomatic: "Kou Xun charged and routed them." },
  { zh: "馮異亦渡河擊朱鮪，鮪走；", literal: "Feng Yi also crossed the river to attack Zhu Wei; Wei fled;", idiomatic: "Feng Yi crossed the river as well and struck Zhu Wei, who fled;" },
  { zh: "異與恂追至洛陽，環城一匝而歸。", literal: "Yi together with Xun pursued to Luoyang, circled the city once, and returned.", idiomatic: "Feng Yi and Kou Xun pursued to Luoyang, circled the walls once, and withdrew." },
  { zh: "自是洛陽震恐，城門晝閉。", literal: "From this Luoyang trembled in terror; the city gates were shut by day.", idiomatic: "From that day Luoyang trembled; the gates stayed shut even in daylight." },
  { zh: "異、恂移檄上狀，諸將入賀，因上尊號。", literal: "Yi and Xun sent dispatches reporting upward; the generals entered to congratulate him and thereupon offered the exalted title.", idiomatic: "Feng Yi and Kou Xun sent memorials reporting their victory; the generals came to congratulate the prince and pressed the exalted title upon him." },
  { zh: "將軍南陽馬武先進曰：「大王雖執謙退，奈宗廟社稷何！", literal: "The general Ma Wu of Nanyang advanced first and said: \"Great King, though you hold to modest withdrawal, what of the ancestral temples and altars of soil and grain!\"", idiomatic: "General Ma Wu of Nanyang spoke first: \"Your Highness clings to modesty, but what of the ancestral temples and the altars of state?\"" },
  { zh: "宜先即尊位，乃議征伐。", literal: "\"It is fitting first to take the exalted position, and only then deliberate on campaigns.\"", idiomatic: "\"Take the throne first, then plan your campaigns.\"" },
  { zh: "今此誰賊而馳騖擊之乎？", literal: "\"Who are these bandits now that you gallop and rush to strike them?\"", idiomatic: "\"Who are these foes that you still ride out to strike?\"" },
  { zh: "」王驚曰：「何將軍出此言！", literal: "\" The prince startled and said: \"General He, how can you speak such words!\"", idiomatic: "\" The prince started and said, \"General He, how dare you speak so!\"" },
  { zh: "可斬也！", literal: "\"You may be beheaded!\"", idiomatic: "\"You deserve execution!\"" },
  { zh: "」乃引軍還薊。", literal: "\" He thereupon led his army back to Ji.", idiomatic: "\" He led his army back to Ji." },
  { zh: "復遣吳漢率耿弇、景丹等十三將軍追尤來等，斬首萬三千餘級，遂窮追至浚靡而還。", literal: "He again sent Wu Han leading Geng Yan, Jing Dan, and twelve other generals—thirteen in all—to pursue Youlai and the others; they beheaded more than thirteen thousand and pressed the pursuit to the limit at Junmi before returning.", idiomatic: "He sent Wu Han with Geng Yan, Jing Dan, and twelve other generals—thirteen in all—to pursue Youlai and his band; they took more than thirteen thousand heads and chased them to Junmi before turning back." },
  { zh: "賊散入遼西、遼東，為烏桓、貊人所鈔擊略盡。", literal: "The bandits scattered into Liaoxi and Liaodong and were raided and struck by the Wuhuan and Mo peoples until nearly all were gone.", idiomatic: "The rebels scattered into Liaoxi and Liaodong; the Wuhuan and Mo peoples raided them until scarcely any remained." },
  { zh: "都護將軍賈復與五校戰於真定，復傷瘡甚。", literal: "The Protector-General Jia Fu fought the Five Commandants at Zhending; Fu's wounds were severe.", idiomatic: "Protector-General Jia Fu fought the Five Commandants at Zhending and was gravely wounded." },
  { zh: "王大驚曰：「我所以不令賈復別將者，為其輕敵也。", literal: "The prince was greatly startled and said: \"The reason I did not let Jia Fu command a separate force was that he treats the enemy lightly.\"", idiomatic: "The prince was deeply alarmed and said, \"I refused to let Jia Fu command a separate force because he is reckless before the enemy.\"" },
  { zh: "果然，失吾名將！", literal: "\"As expected—I have lost my famed general!\"", idiomatic: "\"As I feared—I have lost a great general!\"" },
  { zh: "聞其婦有孕，生女邪，我子娶之；", literal: "\"I hear his wife is with child: if a girl is born, my son shall marry her;", idiomatic: "\"I hear his wife is with child. If she bears a daughter, my son shall marry her;" },
  { zh: "生男邪，我女嫁之；", literal: "if a boy is born, my daughter shall marry him;", idiomatic: "if a son, my daughter shall marry him;" },
  { zh: "不令其憂妻子也。", literal: "I will not let him grieve over wife and children.\"", idiomatic: "he shall not grieve for wife or child.\"" },
  { zh: "」復病尋愈，追及王於薊，相見甚歡。", literal: "\" Fu's illness soon healed; he pursued and overtook the prince at Ji, and their meeting was very joyful.", idiomatic: "\" Jia Fu soon recovered, overtook the prince at Ji, and their reunion was joyful." },
  { zh: "還至中山，諸將復上尊號；", literal: "Returning to Zhongshan, the generals again offered the exalted title;", idiomatic: "On the return to Zhongshan the generals again pressed the exalted title upon him;" },
  { zh: "王又不聽。", literal: "the prince again would not heed them.", idiomatic: "again he refused." },
  { zh: "行到南平棘，諸將復固請之；", literal: "Marching to Nanpingji, the generals again firmly pressed him;", idiomatic: "At Nanpingji the generals pressed him again;" },
  { zh: "王不許。", literal: "the prince did not grant it.", idiomatic: "again he refused." },
  { zh: "諸將且出，耿純進曰：「天下士大夫，捐親戚，棄土壤，從大王於矢石之間者，其計固望攀龍鱗，附鳳翼，以成其所志耳。", literal: "As the generals were about to withdraw, Geng Chun advanced and said: \"The gentlemen of the realm who have cast aside kin, abandoned their native soil, and followed the Great King amid flying stones and arrows—their plan has always been to climb the dragon's scales and cling to the phoenix's wings, to fulfill the aims they cherish.\"", idiomatic: "As the generals were leaving, Geng Chun stepped forward and said, \"The scholars who abandoned kin and homeland to follow Your Highness through arrow and stone did so hoping to touch the dragon's scales and cling to the phoenix's wings—to fulfill their ambitions.\"" },
  { zh: "今大王留時逆眾，不正號位，純恐士大夫望絕計窮，則有去歸之思，無為久自苦也。", literal: "\"Now the Great King lingers, going against the host, and will not set right his title and rank; Chun fears the gentlemen's hopes will end and their plans reach exhaustion—then they will think of leaving and returning. Do not long afflict yourself for nothing.\"", idiomatic: "\"Now you linger against the will of your followers and will not take the throne. I fear that when their hopes fail and their plans reach an end, they will think of leaving you. Do not torment yourself—and us—any longer.\"" },
  { zh: "大眾一散，難可復合。", literal: "Once the great host scatters, it is hard to reunite.", idiomatic: "Once the great host scatters, it is hard to reunite." },
  { zh: "」純言甚誠切，王深感曰：「吾將思之。", literal: "\" Chun's words were very sincere and earnest; the King was deeply moved and said: \"I shall think on it.", idiomatic: "\" Chun's words were very sincere and earnest; the King was deeply moved and said: \"I shall think on it." },
  { zh: "行至鄗，召馮異〔詣鄗〕<ref>召馮異〔詣鄗〕章校「十二行本『異』下有『詣鄗』二字；", literal: "When he reached Hao he summoned Feng Yi [to come to Hao]<ref>Summon Feng Yi [to Hao]: Zhang's collation notes that the twelve-line edition has the two characters \"to Hao\" after \"Yi\";", idiomatic: "When he reached Hao he summoned Feng Yi [to come to Hao]<ref>Summon Feng Yi [to Hao]: Zhang's collation notes that the twelve-line edition has the two characters \"to Hao\" after \"Yi\";" },
  { zh: "乙十一行本同；", literal: "the Yi eleven-line edition agrees;", idiomatic: "the Yi eleven-line edition agrees;" },
  { zh: "孔本同；", literal: "Kong's edition agrees;", idiomatic: "Kong's edition agrees;" },
  { zh: "張校同。", literal: "Zhang's collation agrees.", idiomatic: "Zhang's collation agrees." },
  { zh: "」《後漢書．馮異傳》同，據補。", literal: "\" The Book of the Later Han, biography of Feng Yi, agrees; supplied on that authority.", idiomatic: "\" The Book of the Later Han, biography of Feng Yi, agrees; supplied on that authority." },
  { zh: "</ref>，問四方動靜。", literal: "</ref> and asked about conditions in the four quarters.", idiomatic: "</ref> and asked about conditions in the four quarters." },
  { zh: "異曰：「更始必敗，宗廟之憂在於大王，宜從眾議！", literal: "Yi said: \"Gengshi is certain to fail; the ancestral temple's peril lies with the Great King—you ought to follow the multitude's counsel!", idiomatic: "Yi said: \"The Gengshi Emperor is certain to fail; the peril to the ancestral temple lies with you, Great King—you ought to follow the multitude's counsel!" },
  { zh: "」會儒生強華自關中奉《赤伏符》來詣王曰：「劉秀髮兵捕不道，四夷雲集龍鬬野，四七之際火為主。", literal: "\" It happened that the scholar Qiang Hua from within the passes presented the Red Talisman and came to the King, saying: \"Liu Xiu raises troops to seize the lawless; the four barbarians gather like clouds, dragons contend in the wilds; at the juncture of four and seven, Fire is master.", idiomatic: "\" It happened that the scholar Qiang Hua from within the passes presented the Red Talisman and came to the King, saying: \"Liu Xiu raises troops to seize the lawless; the four barbarians gather like clouds, dragons contend in the wilds; at the juncture of four and seven, Fire is master." },
  { zh: "」群臣因復奏請。", literal: "\" The ministers thereupon again memorialized and requested.", idiomatic: "\" The ministers thereupon again memorialized and requested." },
  { zh: "六月，己未，王即皇帝位于鄗南；", literal: "In the sixth month, on the day jiwei, the King ascended the imperial throne south of Hao;", idiomatic: "In the sixth month, on the day jiwei, the King ascended the imperial throne south of Hao;" },
  { zh: "改元，大赦。", literal: "he changed the era name and proclaimed a general amnesty.", idiomatic: "he changed the era name and proclaimed a general amnesty." },
  { zh: "7鄧禹圍安邑，數月未下，更始大將軍樊參將數萬人度大陽，欲攻禹。", literal: "7 Deng Yu besieged Anyi for several months without taking it; Gengshi's Grand General Fan Can led several tens of thousands across Dayang, intending to attack Yu.", idiomatic: "Deng Yu besieged Anyi for several months without taking it; the Gengshi Emperor's Grand General Fan Can led several tens of thousands across Dayang, intending to attack Yu." },
  { zh: "禹逆擊於解南，斬之。", literal: "Yu met and struck him south of Jie and beheaded him.", idiomatic: "Yu met and struck him south of Jie and beheaded him." },
  { zh: "王匡、成丹、劉均合軍十餘萬，復共擊禹，禹軍不利。", literal: "Wang Kuang, Cheng Dan, and Liu Jun combined armies of more than a hundred thousand and again jointly attacked Yu; Yu's army was unfavorable.", idiomatic: "Wang Kuang, Cheng Dan, and Liu Jun combined armies of more than a hundred thousand and again attacked Yu together; Yu's army fared badly." },
  { zh: "明日，癸亥，匡等以六甲窮日，不出，禹因得更治兵。", literal: "The next day, on the day guihai, Kuang and the others, because it was the last day of the six jia cycle, did not come out; Yu thereby was able to reorganize his troops again.", idiomatic: "The next day, on the day guihai, Kuang and the others, because it was the last day of the six jia cycle, did not come out; Yu thereby was able to reorganize his troops." },
  { zh: "甲子，匡悉軍出攻禹。", literal: "On the day jiazi, Kuang led out his entire army to attack Yu.", idiomatic: "On the day jiazi, Kuang led out his entire army to attack Yu." },
  { zh: "禹令軍中無得妄動，既至營下，因傳發諸將，鼓而並進，大破之。", literal: "Yu ordered that within the army none might move rashly; when they had reached below the camp, he then transmitted orders to the generals, drummed, and advanced together, routing them utterly.", idiomatic: "Yu ordered that none in the army move rashly; when they had reached below the camp, he transmitted orders to the generals, drummed, and advanced together, routing them utterly." },
  { zh: "匡等皆走，禹追斬均及河東太守楊寶，遂定河東，匡等奔還長安。", literal: "Kuang and the others all fled; Yu pursued and beheaded Jun and Hedong Administrator Yang Bao, thereupon pacified Hedong, and Kuang and the others fled back to Chang'an.", idiomatic: "Kuang and the others all fled; Yu pursued and beheaded Liu Jun and Hedong Administrator Yang Bao, thereby pacified Hedong, and Kuang and the others fled back to Chang'an." },
  { zh: "張卬與諸將議曰：「赤眉旦暮且至，見滅不久，不如掠長安，東歸南陽；", literal: "Zhang Ang and the generals deliberated, saying: \"The Red Eyebrows will arrive before long; our destruction is not far off—better to plunder Chang'an and return east to Nanyang;", idiomatic: "Zhang Ang and the generals deliberated, saying: \"The Red Eyebrows will arrive before long; our destruction is not far off—better to plunder Chang'an and return east to Nanyang;" },
  { zh: "事若不集，復入湖池中為盜耳！", literal: "if the affair does not succeed, we can again enter the lake marshes and be bandits!", idiomatic: "if the affair does not succeed, we can again take to the lake marshes and be bandits!" },
  { zh: "」乃共入，說更始；", literal: "\" They then together entered and urged Gengshi;", idiomatic: "\" They then together entered and urged the Gengshi Emperor;" },
  { zh: "更始怒不應，莫敢復言。", literal: "Gengshi was angry and did not assent; none dared speak again.", idiomatic: "The Gengshi Emperor was angry and did not assent; none dared speak again." },
  { zh: "更始使王匡、陳牧、成丹、趙萌屯新豐，李松軍槁，以拒赤眉。", literal: "Gengshi sent Wang Kuang, Chen Mu, Cheng Dan, and Zhao Meng to garrison Xinfeng, and Li Song's army at Gao, to resist the Red Eyebrows.", idiomatic: "The Gengshi Emperor sent Wang Kuang, Chen Mu, Cheng Dan, and Zhao Meng to garrison Xinfeng and Li Song's army at Gao to resist the Red Eyebrows." },
  { zh: "張卬、廖湛、胡殷、申屠建與隗囂合謀，欲以立秋日貙膢時共劫更始，俱成前計。", literal: "Zhang Ang, Liao Zhan, Hu Yin, Shentu Jian, and Wei Ao together plotted, wishing on the day of Beginning of Autumn at the time of the autumn sacrifice jointly to seize Gengshi and together carry out the earlier plan.", idiomatic: "Zhang Ang, Liao Zhan, Hu Yin, Shentu Jian, and Wei Ao plotted together to seize the Gengshi Emperor on the day of Beginning of Autumn at the time of the autumn sacrifice and carry out their earlier plan." },
  { zh: "更始知之，託病不出，召張卬等入，將悉誅之，唯隗囂稱疾不入，會客王遵、周宗等勒兵自守。", literal: "Gengshi learned of it, pleaded illness and did not come out, summoned Zhang Ang and the others in, and was about to execute them all; only Wei Ao claimed illness and did not enter, while his guests Wang Zun, Zhou Zong, and others mustered troops to defend themselves.", idiomatic: "The Gengshi Emperor learned of it, pleaded illness and did not appear, summoned Zhang Ang and the others in, and was about to execute them all; only Wei Ao claimed illness and did not enter, while his guests Wang Zun, Zhou Zong, and others mustered troops to defend themselves." },
  { zh: "更始狐疑不決，卬、湛、殷疑有變，遂突出。", literal: "Gengshi was hesitant and could not decide; Ang, Zhan, and Yin suspected there was a change and thereupon broke out.", idiomatic: "The Gengshi Emperor hesitated and could not decide; Ang, Zhan, and Yin suspected a trap and broke out." },
  { zh: "獨申屠建在，更始斬建，使執金吾鄧曄將兵圍隗囂第。", literal: "Only Shentu Jian remained; Gengshi beheaded Jian and sent Bearer of the Mace Deng Ye to lead troops and besiege Wei's residence.", idiomatic: "Only Shentu Jian remained; the Gengshi Emperor beheaded him and sent Bearer of the Mace Deng Ye to lead troops and besiege Wei's residence." },
  { zh: "卬、湛、殷勒兵燒門，入戰宮中，更始大敗。", literal: "Ang, Zhan, and Yin mustered troops, burned the gates, entered and fought within the palace, and Gengshi was utterly defeated.", idiomatic: "Ang, Zhan, and Yin mustered troops, burned the gates, fought within the palace, and the Gengshi Emperor was utterly defeated." },
  { zh: "囂亦潰圍，走歸天水。", literal: "Ao also broke the siege and fled back to Tianshui.", idiomatic: "Ao also broke the siege and fled back to Tianshui." },
  { zh: "明旦，更始東奔趙萌於新豐。", literal: "At dawn the next day, Gengshi fled east to Zhao Meng at Xinfeng.", idiomatic: "At dawn the next day, the Gengshi Emperor fled east to Zhao Meng at Xinfeng." },
  { zh: "更始復疑王匡、陳牧、成丹與張卬等同謀，乃並召入；", literal: "Gengshi again suspected Wang Kuang, Chen Mu, and Cheng Dan of plotting with Zhang Ang and the others, and therefore summoned them all in;", idiomatic: "The Gengshi Emperor again suspected Wang Kuang, Chen Mu, and Cheng Dan of plotting with Zhang Ang and the others and summoned them all in;" },
  { zh: "牧、丹先至，即斬之。", literal: "Mu and Dan arrived first and were immediately beheaded.", idiomatic: "Mu and Dan arrived first and were immediately beheaded." },
  { zh: "王匡懼，將兵入長安，與張卬等合。", literal: "Wang Kuang was afraid, led troops into Chang'an, and joined Zhang Ang and the others.", idiomatic: "Wang Kuang was afraid, led troops into Chang'an, and joined Zhang Ang and the others." },
  { zh: "8赤眉進至華陰，軍中有齊巫，常鼓舞祠城陽景王，巫狂言：「景王大怒曰：『當為縣官，何故為賊！", literal: "8 The Red Eyebrows advanced to Huayin; in the army there was a Qi shaman who often drummed and danced in sacrifice to King Jing of Chengyang; the shaman raved, saying: \"King Jing was greatly angered and said: 'You ought to serve as officials of the state—why act as bandits!", idiomatic: "The Red Eyebrows advanced to Huayin; in the army there was a Qi shaman who often drummed and danced in sacrifice to King Jing of Chengyang; the shaman raved, saying: \"King Jing was greatly angered and said: 'You ought to serve as officials of the state—why act as bandits!" },
  { zh: "』」有笑巫者輒病，軍中驚動。", literal: "'\" Whoever laughed at the shaman immediately fell ill, and the army was shaken.", idiomatic: "'\" Whoever laughed at the shaman immediately fell ill, and the army was shaken." },
  { zh: "方望弟陽說樊崇等曰：「今將軍擁百萬之眾，西向帝城，而無稱號，名為群賊，不可以久。", literal: "Fang Wang's younger brother Yang urged Fan Chong and the others, saying: \"Now the general holds a host of a million men and faces west toward the imperial city, yet has no title—you are called a band of thieves; this cannot last long.", idiomatic: "Fang Wang's younger brother Yang urged Fan Chong and the others, saying: \"Now you hold a host of a million men and face west toward the imperial city, yet have no title—you are called a band of thieves; this cannot last." },
  { zh: "不如立宗室，挾義誅伐，以此號令，誰敢不從！", literal: "Better to establish a member of the imperial clan, take righteousness as your banner for punitive campaigns, and with such a command—who would dare not follow!", idiomatic: "Better to establish a member of the imperial clan, take righteousness as your banner for punitive campaigns, and with such a command—who would dare not follow!" },
  { zh: "」崇等以為然，而巫言益甚。", literal: "\" Chong and the others thought it right, but the shaman's words grew ever stronger.", idiomatic: "\" Chong and the others agreed, but the shaman's words grew ever stronger." },
  { zh: "前至鄭，乃相與議曰：「今迫近長安，而鬼神若此，當求劉氏共尊立之。", literal: "When they advanced to Zheng, they then deliberated together, saying: \"Now we press close to Chang'an, and the spirits and ghosts are thus—we ought to seek out the Liu clan and together honor and establish one.", idiomatic: "When they advanced to Zheng, they deliberated together, saying: \"Now we press close to Chang'an, and the spirits are thus—we ought to seek out the Liu clan and together honor and establish one." },
  { zh: "先是，赤眉過式，掠故式侯萌之子恭、茂、盆子三人自隨。", literal: "Earlier, when the Red Eyebrows passed through Shi, they seized and took along the former Marquis of Shi's sons Gong, Mao, and Penzi.", idiomatic: "Earlier, when the Red Eyebrows passed through Shi, they seized and took along the former Marquis of Shi's sons Gong, Mao, and Penzi." },
  { zh: "恭少習《尚書》，隨樊崇等降更始於洛陽，復封式侯，為侍中，在長安。", literal: "Gong in youth studied the Documents; he followed Fan Chong and the others in surrendering to Gengshi at Luoyang, was again enfeoffed as Marquis of Shi, made Palace Attendant, and was in Chang'an.", idiomatic: "Gong had studied the Documents in youth; he followed Fan Chong and the others in surrendering to the Gengshi Emperor at Luoyang, was again enfeoffed as Marquis of Shi, made Palace Attendant, and was in Chang'an." },
  { zh: "茂與盆子留軍中，屬右校卒史劉俠卿，主牧牛。", literal: "Mao and Penzi remained in the army, attached to Right Column company clerk Liu Xiaqing, who was in charge of herding cattle.", idiomatic: "Mao and Penzi remained in the army under Right Column company clerk Liu Xiaqing, who was in charge of herding cattle." },
  { zh: "及崇等欲立帝，求軍中景王後，得七十餘人，唯茂、盆子及前西安侯孝最為近屬。", literal: "When Chong and the others wished to establish an emperor, they sought descendants of King Jing in the army and found more than seventy; only Mao, Penzi, and the former Marquis of Xi'an Xiao were closest in kinship.", idiomatic: "When Chong and the others wished to establish an emperor, they sought descendants of King Jing in the army and found more than seventy; only Mao, Penzi, and the former Marquis of Xi'an Xiao were closest in kinship." },
  { zh: "崇等曰：「聞古者天子將兵稱上將軍。", literal: "Chong and the others said: \"We have heard that in antiquity when the Son of Heaven led troops he was styled supreme general.", idiomatic: "Chong and the others said: \"We have heard that in antiquity when the Son of Heaven led troops he was styled supreme general." },
  { zh: "」乃書札為符曰：「上將軍」。", literal: "\" They then wrote on slips as talismans the words \"supreme general.\"", idiomatic: "\" They then wrote on slips as talismans the words \"supreme general.\"" },
  { zh: "又以兩空札置笥中，於鄭北設壇場，祠城陽景王，諸三老、從事皆大會。", literal: "They also placed two blank slips in a box; north of Zheng they set up an altar platform, sacrificed to King Jing of Chengyang, and all the village elders and staff officers held a great assembly.", idiomatic: "They also placed two blank slips in a box; north of Zheng they set up an altar, sacrificed to King Jing of Chengyang, and all the village elders and staff officers held a great assembly." },
  { zh: "列盆子等三人居中立，以年次探札，盆子最幼，後探，得符；", literal: "They arrayed Penzi and the three others standing in the center; by order of age they drew slips—Penzi was youngest and drew last, and obtained the talisman;", idiomatic: "They arrayed Penzi and the three others standing in the center; by order of age they drew slips—Penzi was youngest and drew last, and obtained the talisman;" },
  { zh: "諸將皆稱臣，拜。", literal: "all the generals styled themselves subjects and bowed.", idiomatic: "all the generals styled themselves subjects and bowed." },
  { zh: "盆子時年十五，被發徙跣，敝衣赭汗，見眾拜，恐畏欲啼。", literal: "Penzi was then fifteen years old, hair unbound, barefoot, in tattered clothes stained with red sweat; when he saw the multitude he bowed, afraid and on the verge of weeping.", idiomatic: "Penzi was then fifteen, hair unbound and barefoot, in tattered clothes stained with red sweat; when he saw the multitude he bowed, afraid and on the verge of weeping." },
  { zh: "茂謂曰：「善臧符！", literal: "Mao said to him: \"Guard the talisman well!", idiomatic: "Mao said to him: \"Guard the talisman well!" },
  { zh: "」盆子即齧折，棄之。", literal: "\" Penzi immediately bit it in two and threw it away.", idiomatic: "\" Penzi immediately bit it in two and threw it away." },
  { zh: "以徐宣為丞相，樊崇為御史大夫，逢安為左大司馬，謝祿為右大司馬，其餘皆列卿、將軍。", literal: "They made Xu Xuan Chancellor, Fan Chong Censor-in-Chief, Feng An Left Grand Marshal, Xie Lu Right Grand Marshal, and the rest were all ranked as ministers and generals.", idiomatic: "They made Xu Xuan Chancellor, Fan Chong Censor-in-Chief, Feng An Left Grand Marshal, Xie Lu Right Grand Marshal, and the rest were all ranked as ministers and generals." },
  { zh: "盆子雖立，猶朝夕拜劉俠卿，時欲出從牧兒戲；", literal: "Though Penzi was established, he still morning and evening bowed to Liu Xiaqing and at times wished to go out and follow the herdboys in play;", idiomatic: "Though Penzi was established, he still morning and evening bowed to Liu Xiaqing and at times wished to go out and play with the herdboys;" },
  { zh: "俠卿怒止之，崇等亦不復候視也。", literal: "Xiaqing angrily stopped him, and Chong and the others also no longer attended and looked in on him.", idiomatic: "Xiaqing angrily stopped him, and Chong and the others also no longer attended him." },
  { zh: "9秋，七月，辛未，帝使使持節拜鄧禹為大司徒，封酇侯，食邑萬戶；", literal: "9 In autumn, the seventh month, on the day xinwei, the Emperor sent an envoy bearing the staff of authority to appoint Deng Yu Grand Master of Works, enfeoff him as Marquis of Zan, with a fief of ten thousand households;", idiomatic: "In autumn, the seventh month, on the day xinwei, the Emperor sent an envoy bearing the staff of authority to appoint Deng Yu Grand Master of Works, enfeoff him as Marquis of Zan, with a fief of ten thousand households;" },
  { zh: "禹時年二十四。", literal: "Yu was then twenty-four years old.", idiomatic: "Yu was then twenty-four years old." },
  { zh: "又議選大司空，帝以《赤伏符》曰「王梁主衛作玄武」，丁丑，以野王令王梁為大司空。", literal: "They again deliberated on selecting a Grand Minister of Works; the Emperor, because the Red Talisman says \"Wang Liang masters Wei and acts as the Dark Warrior,\" on the day dingchou made Ye County magistrate Wang Liang Grand Minister of Works.", idiomatic: "They again deliberated on selecting a Grand Minister of Works; because the Red Talisman says \"Wang Liang masters Wei and acts as the Dark Warrior,\" on the day dingchou the Emperor made Ye County magistrate Wang Liang Grand Minister of Works." },
  { zh: "又欲以讖文用平狄將軍孫咸行大司馬，眾咸不悅。", literal: "He also wished to use prophecy-text to employ Pacify-the-Di General Sun Xian to act as Grand Marshal; the multitude were all displeased.", idiomatic: "He also wished to use prophecy-text to employ Pacify-the-Di General Sun Xian as Grand Marshal; the multitude were all displeased." },
  { zh: "壬午，以吳漢為大司馬。", literal: "On the day renwu he made Wu Han Grand Marshal.", idiomatic: "On the day renwu he made Wu Han Grand Marshal." },
  { zh: "初，更始以琅邪伏湛為平原太守。", literal: "Earlier, Gengshi had made Langye's Fu Zhan Administrator of Pingyuan.", idiomatic: "Earlier, the Gengshi Emperor had made Fu Zhan of Langye Administrator of Pingyuan." },
  { zh: "時天下兵起，湛獨晏然，撫循百姓。", literal: "At the time troops were rising throughout the empire; Zhan alone remained tranquil and comforted and guided the common people.", idiomatic: "At the time troops were rising throughout the empire; Zhan alone remained tranquil and comforted the common people." },
  { zh: "門下督謀為湛起兵，湛收斬之。", literal: "A gate-house supervisor plotted to raise troops for Zhan; Zhan seized and beheaded him.", idiomatic: "A gate-house supervisor plotted to raise troops for Zhan; Zhan seized and beheaded him." },
  { zh: "於是吏民信向，平原一境賴湛以全。", literal: "Thereupon officials and people trusted and turned to him; the whole territory of Pingyuan relied on Zhan to be preserved.", idiomatic: "Thereupon officials and people trusted him; the whole territory of Pingyuan was preserved through Zhan." },
  { zh: "帝徵湛為尚書，使典定舊制。", literal: "The Emperor summoned Zhan as Master of Writing and had him oversee and fix the old regulations.", idiomatic: "The Emperor summoned Zhan as Master of Writing and had him oversee and fix the old regulations." },
  { zh: "又以鄧禹西征，拜湛為司直，行大司徒事。", literal: "Also, because Deng Yu was campaigning west, he appointed Zhan Director of Integrity, acting in Grand Master of Works affairs.", idiomatic: "Also, because Deng Yu was campaigning west, he appointed Zhan Director of Integrity to act in Grand Master of Works affairs." },
  { zh: "車駕每出征伐，常留鎮守。", literal: "Whenever the imperial carriage went out on punitive campaigns, Zhan was regularly left to garrison and guard.", idiomatic: "Whenever the imperial carriage went on campaign, Zhan was regularly left to garrison and guard." },
  { zh: "10鄧禹自汾陰渡河，入夏陽，更始左輔都尉公乘歙引其眾十萬，與左馮翊兵共拒禹於衙；", literal: "10 Deng Yu from Fenyin crossed the river, entered Xiayang; Gengshi's Left Assistant Commandant Gongcheng Xi led his host of a hundred thousand, and together with Left Fengyi troops jointly resisted Yu at Ya;", idiomatic: "Deng Yu crossed the river from Fenyin and entered Xiayang; the Gengshi Emperor's Left Assistant Commandant Gongcheng Xi led his host of a hundred thousand and, together with Left Fengyi troops, resisted Yu at Ya;" },
  { zh: "禹復破走之。", literal: "Yu again defeated them and drove them off.", idiomatic: "Yu again defeated them and drove them off." },
  { zh: "宗室劉茂聚眾京、密間，自稱厭新將軍，攻下穎川、汝南，眾十餘萬人。", literal: "A clansman, Liu Mao, gathered a host between Jing and Mi, styled himself Resist-the-New General, attacked and took Yingchuan and Runan, and his host numbered more than a hundred thousand.", idiomatic: "The clansman Liu Mao gathered a host between Jing and Mi, styled himself Resist-the-New General, took Yingchuan and Runan, and mustered more than a hundred thousand." },
  { zh: "帝使驃騎大將軍景丹、建威大將軍耿弇、強弩將軍陳俊攻之。", literal: "The Emperor sent Rapid Cavalry Grand General Jing Dan, Establish Authority Grand General Geng Yan, and Strong Crossbow General Chen Jun to attack him.", idiomatic: "The Emperor sent Rapid Cavalry Grand General Jing Dan, Establish Authority Grand General Geng Yan, and Strong Crossbow General Chen Jun to attack him." },
  { zh: "茂來降，封為中山王。", literal: "Mao came and surrendered and was enfeoffed as King of Zhongshan.", idiomatic: "Mao came and surrendered and was enfeoffed as King of Zhongshan." },
  { zh: "11己亥<ref>己亥七月丁卯朔，無己亥日。", literal: "11 On the day jihai<ref>On jihai: the seventh month's new moon of dingmao has no day jihai.", idiomatic: "On the day jihai<ref>On jihai: the seventh month's new moon of dingmao has no day jihai." },
  { zh: "</ref>，帝幸懷，遣耿弇、陳俊軍五社津，備滎陽以東；", literal: "</ref> the Emperor visited Huai, sent Geng Yan and Chen Jun's armies to Wushe Ford to guard east of Xingyang;", idiomatic: "</ref> the Emperor visited Huai, sent the armies of Geng Yan and Chen Jun to Wushe Ford to guard east of Xingyang;" },
  { zh: "使吳漢率建〔義〕(", literal: "and had Wu Han lead Establish-[Righteousness](", idiomatic: "and had Wu Han lead Establish-[Righteousness](" },
  { zh: "議)", literal: "Purpose)", idiomatic: "Purpose)" },
  { zh: "大將軍朱祜等十一將軍<ref>使吳漢率建〔義〕(", literal: "Grand General Zhu You and eleven other generals<ref>Had Wu Han lead Establish-[Righteousness](", idiomatic: "Grand General Zhu You and eleven other generals<ref>Had Wu Han lead Establish-[Righteousness](" },
  { zh: "議)", literal: "Purpose)", idiomatic: "Purpose)" },
  { zh: "大將軍朱祜等十一將軍此「建議」當作「建義」，據改。", literal: "Grand General Zhu You and eleven other generals: this \"Establish Purpose\" should read \"Establish Righteousness,\" emended on that authority.", idiomatic: "Grand General Zhu You and eleven other generals: this \"Establish Purpose\" should read \"Establish Righteousness,\" emended on that authority." },
  { zh: "</ref>，圍朱鮪於洛陽。", literal: "</ref> to besiege Zhu Wei at Luoyang.", idiomatic: "</ref> to besiege Zhu Wei at Luoyang." },
  { zh: "八月，進幸河陽。", literal: "In the eighth month he advanced to favor Heyang.", idiomatic: "In the eighth month he advanced to Heyang." },
  { zh: "12李松自槁引兵還，從更始與趙萌共攻王匡、張卬於長安。", literal: "12 Li Song from Gao led his troops back, followed Gengshi, and together with Zhao Meng attacked Wang Kuang and Zhang Ang in Chang'an.", idiomatic: "Li Song led his troops back from Gao, followed the Gengshi Emperor, and together with Zhao Meng attacked Wang Kuang and Zhang Ang in Chang'an." },
  { zh: "連戰月餘，匡等敗走，更始徒居長信宮。", literal: "They fought continuously for more than a month; Kuang and the others were defeated and fled, and Gengshi moved his residence to Changxin Palace.", idiomatic: "They fought continuously for more than a month; Kuang and the others were defeated and fled, and the Gengshi Emperor moved to Changxin Palace." },
  { zh: "赤眉至高陵，王匡、張卬等迎降之，遂共連兵進攻東都門。", literal: "The Red Eyebrows reached Gaoling; Wang Kuang, Zhang Ang, and the others came out to welcome and surrender to them, and thereupon together linked forces and advanced to attack the Eastern Capital Gate.", idiomatic: "The Red Eyebrows reached Gaoling; Wang Kuang, Zhang Ang, and the others came out to welcome and surrender to them, and together advanced to attack the Eastern Capital Gate." },
  { zh: "李松出戰，赤眉生得松。", literal: "Li Song went out to fight; the Red Eyebrows captured Song alive.", idiomatic: "Li Song went out to fight; the Red Eyebrows captured him alive." },
  { zh: "松弟況為城門校尉，開門納之。", literal: "Song's younger brother Kuang was Colonel of the City Gates and opened the gate to admit them.", idiomatic: "Song's younger brother Kuang was Colonel of the City Gates and opened the gate to admit them." },
  { zh: "九月，赤眉入長安。", literal: "In the ninth month the Red Eyebrows entered Chang'an.", idiomatic: "In the ninth month the Red Eyebrows entered Chang'an." },
  { zh: "更始單騎走，從廚城門出。", literal: "Gengshi fled alone on horseback and went out through the Kitchen City Gate.", idiomatic: "The Gengshi Emperor fled alone on horseback and went out through the Kitchen City Gate." },
  { zh: "式侯恭以赤眉立其弟，自系詔獄；", literal: "Marquis of Shi Gong, because the Red Eyebrows had established his younger brother, bound himself and entered the imperial prison;", idiomatic: "Marquis of Shi Gong, because the Red Eyebrows had established his younger brother, bound himself and entered the imperial prison;" },
  { zh: "聞更始敗走，乃出，見定陶王祉。", literal: "hearing that Gengshi had been defeated and fled, then came out and met King of Dingtao Zhi.", idiomatic: "hearing that the Gengshi Emperor had been defeated and fled, then came out and met King of Dingtao Liu Zhi." },
  { zh: "祉為之除械，相與從更始於渭濱。", literal: "Zhi removed his bonds for him, and together they followed Gengshi on the Wei bank.", idiomatic: "Zhi removed his bonds and together they followed the Gengshi Emperor on the Wei bank." },
  { zh: "右輔都尉嚴本，恐失更始為赤眉所誅，即將更始至高陵，本將兵宿衛，其實圍之。", literal: "Right Assistant Commandant Yan Ben, fearing he would lose Gengshi and be executed by the Red Eyebrows, immediately took Gengshi to Gaoling; Ben led troops to lodge and guard him—in fact he surrounded him.", idiomatic: "Right Assistant Commandant Yan Ben, fearing he would lose the Gengshi Emperor and be executed by the Red Eyebrows, immediately took him to Gaoling; Ben led troops to lodge and guard him—in fact he surrounded him." },
  { zh: "更始將相皆降赤眉，獨丞相曹竟不降，手劍格死。", literal: "Gengshi's generals and ministers all surrendered to the Red Eyebrows; only Chancellor Cao Jing did not surrender and was killed fighting hand to hand with his sword.", idiomatic: "The Gengshi Emperor's generals and ministers all surrendered to the Red Eyebrows; only Chancellor Cao Jing did not surrender and was killed fighting hand to hand with his sword." },
  { zh: "13辛未，詔封更始為淮陽王；", literal: "13 On the day xinwei an edict enfeoffed Gengshi as King of Huaiyang;", idiomatic: "On the day xinwei an edict enfeoffed the Gengshi Emperor as King of Huaiyang;" },
  { zh: "吏民敢有賊害者，罪同大逆；", literal: "officials or common people who dared harm him were guilty of the same crime as great treason;", idiomatic: "any official or commoner who dared harm him was guilty of the same crime as great treason;" },
  { zh: "其送詣吏者封列侯。", literal: "whoever delivered him to the authorities was enfeoffed as a ranked marquis.", idiomatic: "whoever delivered him to the authorities was enfeoffed as a ranked marquis." },
  { zh: "14初，宛人卓茂，寬仁恭愛，恬蕩樂道，雅實不為華貌，行己在於清濁之間，自束髮至白首，與人未嘗有爭競，鄉黨故舊，雖行能與茂不同，而皆愛慕欣欣焉。", literal: "14 Earlier, Zhuo Mao of Wan was broad, benevolent, respectful, and loving, tranquil and easy and delighting in the Way, refined and solid and not making a showy appearance; in conducting himself he stood between the clear and the turbid—from tying his hair until white-haired old age he never had contention or rivalry with others; fellow villagers and old friends, though conduct and ability differed from Mao's, all loved and admired him with joy.", idiomatic: "Earlier, Zhuo Mao of Wan was broad, benevolent, respectful, and loving, tranquil and easy and delighting in the Way, refined and solid without showy appearance; in conduct he stood between the clear and the turbid—from youth until white-haired old age he never quarreled with anyone; fellow villagers and old friends, though their conduct and ability differed from his, all loved and admired him gladly." },
  { zh: "哀、平間為密令，視民如子，舉善而教，口無惡言，吏民親愛，不忍欺之。", literal: "Between the Ai and Ping reigns he was magistrate of Mi, regarded the people as children, promoted the good and taught them, had no evil words on his lips; officials and people were affectionate toward him and could not bear to deceive him.", idiomatic: "Between the Ai and Ping reigns he was magistrate of Mi, regarded the people as children, promoted the good and taught them, and never spoke evil words; officials and people were affectionate toward him and could not bear to deceive him." },
  { zh: "民嘗有言部亭長受其米肉遺者，茂曰：「亭長為從汝求乎，為汝有事囑之而受乎，將平居自以恩意遺之乎？", literal: "The people once said that a district station chief had received gifts of grain and meat from them; Mao said: \"Did the station chief ask it of you, or did you have some matter to entrust to him and therefore give it, or did he on his own in ordinary times give it out of kindness?", idiomatic: "The people once said that a district station chief had received gifts of grain and meat from them; Mao said: \"Did the station chief ask it of you, or did you have some matter to entrust to him and therefore give it, or did he on his own in ordinary times give it out of kindness?" },
  { zh: "」民曰：「往遺之耳。", literal: "\" The people said: \"We simply gave them as gifts in the past.", idiomatic: "\" The people said, \"We simply gave them as gifts in the past.\"" },
  { zh: "」茂曰：「遺之而受，何故言邪？", literal: "\" Mao said: \"You gave them and he accepted—why speak of it?", idiomatic: "\" Mao said, \"You gave them and he accepted—why bring it up?\"" },
  { zh: "」民曰：「竊聞賢明之君，使民不畏吏，吏不取民。", literal: "\" The people said: \"I have heard that a worthy and enlightened ruler makes the people unafraid of officials and officials do not take from the people.", idiomatic: "\" The people said, \"I have heard that a worthy and enlightened ruler makes the people unafraid of officials and officials do not take from the people.\"" },
  { zh: "今我畏吏，是以遺之；", literal: "Now I fear the official, and therefore I gave them;", idiomatic: "Now I fear the official, and therefore I gave them;" },
  { zh: "吏既卒受，故來言耳。", literal: "the official has in the end accepted them, and so I have come to report it.", idiomatic: "the official has in the end accepted them, and so I have come to report it." },
  { zh: "」茂曰：「汝為敝民矣！", literal: "\" Mao said: \"You are a benighted commoner!", idiomatic: "\" Mao said, \"You are a benighted commoner!\"" },
  { zh: "凡人所以群居不亂，異於禽獸者，以有仁愛禮義，知相敬事也。", literal: "The reason ordinary men can dwell together without disorder and differ from birds and beasts is that they have benevolence, love, ritual, and righteousness and know how to respect and serve one another.", idiomatic: "The reason people can live together without disorder and differ from birds and beasts is that they have benevolence, ritual, and righteousness and know how to respect and serve one another." },
  { zh: "汝獨不欲修之，寧能高飛遠走，不在人間邪！", literal: "You alone do not wish to cultivate them—can you fly high and run far and not be among men?!", idiomatic: "You alone refuse to cultivate them—can you fly away and live apart from mankind?!\"" },
  { zh: "吏顧不當乘威力強請求耳。", literal: "The official surely ought not to use his power to force demands.", idiomatic: "The official surely ought not to use his power to force demands." },
  { zh: "亭長素善吏，歲時遺之，禮也。", literal: "The station chief has long been on good terms with the official; giving him gifts at the seasons is ritual propriety.", idiomatic: "The station chief has long been on good terms with the official; giving him seasonal gifts is proper courtesy." },
  { zh: "」民曰：「苟如此，律何故禁之？", literal: "\" The people said: \"If so, why does the law forbid it?", idiomatic: "\" The people said, \"If so, why does the law forbid it?\"" },
  { zh: "」茂笑曰：「律設大法，禮順人情。", literal: "\" Mao laughed and said: \"The law sets forth the great standard; ritual accords with human feeling.", idiomatic: "\" Mao laughed and said, \"The law sets forth the great standard; ritual accords with human feeling." },
  { zh: "今我以禮教汝，汝必無怨惡；", literal: "Now if I teach you by ritual, you will surely harbor no resentment;", idiomatic: "Now if I teach you by ritual, you will surely harbor no resentment;" },
  { zh: "以律治汝，汝何所措其手足乎！", literal: "if I govern you by the law, where will you set hand or foot?!", idiomatic: "if I govern you by the law, where will you set hand or foot?!\"" },
  { zh: "一門之內，小者可論，大者可殺也。", literal: "Within one household, the lesser may be argued, the greater may be put to death.", idiomatic: "Within one household, the lesser offense may be argued, the greater may be punished with death." },
  { zh: "且歸念之。", literal: "Go home for now and reflect on it.", idiomatic: "Go home for now and reflect on it.\"" },
  { zh: "」初，茂到縣，有所廢置，吏民笑之，鄰城聞者皆蚩其不能。", literal: "\" Earlier, when Mao reached the county he abolished and established various things; officials and commoners laughed at him, and those in neighboring cities who heard of it all scoffed at his incompetence.", idiomatic: "\" Earlier, when Mao reached the county he abolished and established various measures; officials and commoners laughed at him, and those in neighboring cities who heard of it all scoffed at his incompetence." },
  { zh: "河南郡為置守令；", literal: "Henan commandery set up a guardian and magistrate for him;", idiomatic: "Henan commandery set up a guardian and magistrate over him;" },
  { zh: "茂不為嫌，治事自若。", literal: "Mao took no offense and governed affairs as before.", idiomatic: "Mao took no offense and governed affairs as before." },
  { zh: "數年，教化大行，道不拾遺；", literal: "After several years, instruction and transformation were greatly carried out, and no one picked up what was lost on the road;", idiomatic: "After several years, instruction and transformation flourished, and no one picked up what was lost on the road;" },
  { zh: "遷京部丞，密人老少皆涕泣隨送。", literal: "he was transferred to be Director in the Capital Department, and old and young of Mi all wept and followed to see him off.", idiomatic: "he was transferred to Director in the Capital Department, and old and young of Mi all wept and followed to see him off." },
  { zh: "及王莽居攝，以病免歸。", literal: "When Wang Mang held the regency, he was dismissed on grounds of illness and returned home.", idiomatic: "When Wang Mang held the regency, he was dismissed on grounds of illness and returned home." },
  { zh: "上即位，先訪求茂，茂時年七十餘。", literal: "When the Emperor took the throne, he first sought out Mao; Mao was then more than seventy.", idiomatic: "When the Emperor took the throne, he first sought out Mao; Mao was then more than seventy." },
  { zh: "甲申，詔曰：「夫名冠天下，當受天下重賞。", literal: "On jiashen an edict said: \"One whose fame crowns all under Heaven ought to receive the realm's weighty reward.", idiomatic: "On jiashen an edict said, \"One whose fame crowns all under Heaven ought to receive the realm's weightiest reward." },
  { zh: "今以茂為太傅，封褒德侯。", literal: "Now Mao is made Grand Tutor and enfeoffed as Marquis of Praising Virtue.", idiomatic: "Now Mao is made Grand Tutor and enfeoffed as Marquis of Praising Virtue.\"" },
  { zh: "臣光曰：孔子稱「舉善而教，不能則勸」，是以舜舉皋陶，湯舉伊尹，而不仁者遠，有德故也。", literal: "Your servant Guang says: Confucius praised \"raise the good and teach; where one cannot, then exhort,\" and therefore Shun raised Gao Yao, Tang raised Yi Yin, and the unbenevolent kept their distance—because there was virtue.", idiomatic: "Sima Guang comments: Confucius praised \"raise the good and teach; where one cannot, then exhort,\" and therefore Shun raised Gao Yao and Tang raised Yi Yin, and the unbenevolent kept their distance—because virtue was present." },
  { zh: "光武即位之初，群雄競逐，四海鼎沸，彼摧堅陷敵之人，權略詭辯之士，方見重於世，而獨能取忠厚之臣，旌循良之吏，拔於草萊之中，實諸群公之首，宜其光復舊物，享祚久長，蓋由知所先務而得其本原故也。", literal: "At the beginning of Guangwu's accession, rival heroes contended in pursuit and the four seas seethed like a cauldron; those who shattered the hard and overran the foe, and masters of power-stratagem and crafty debate, were just then valued in the world—yet he alone could take loyal and honest ministers, honor diligent and good officials, draw them from among the weeds, and place them at the head of all the lords. It is fitting that he restored the old patrimony and enjoyed the throne long—surely because he knew what to put first and grasped the root and origin.", idiomatic: "At the beginning of Guangwu's reign, rival heroes contended and the four seas seethed; men who shattered the hard and overran the foe and masters of stratagem and crafty debate were then valued in the world—yet he alone could take loyal and honest ministers, honor diligent and good officials, draw them from humble ranks, and place them at the head of all his lords. It is fitting that he restored the old patrimony and enjoyed the throne long—surely because he knew what to put first and grasped the root cause." },
  { zh: "15諸將圍洛陽數月，朱鮪堅守不下。", literal: "15. The generals besieged Luoyang for several months; Zhu Wei held firm and would not yield.", idiomatic: "15. The generals besieged Luoyang for several months; Zhu Wei held firm and would not yield." },
  { zh: "帝以廷尉岑彭嘗為鮪校尉，令往說之。", literal: "The Emperor, because Director of Justice Cen Peng had once been Wei's commandant, ordered him to go and persuade him.", idiomatic: "The Emperor, because Director of Justice Cen Peng had once been Wei's commandant, ordered him to go and persuade him." },
  { zh: "鮪在城上，彭在城下，為陳成敗。", literal: "Wei was on the wall and Peng below the wall, setting forth success and failure.", idiomatic: "Wei was on the wall and Peng below, setting forth the odds of success and failure." },
  { zh: "鮪曰：「大司徒被害時，鮪與共謀，又諫更始無遣蕭王北伐，誠自知罪深，不敢降！", literal: "Wei said: \"When the Grand Master of Works was killed, Wei joined in the plot, and also remonstrated with the Gengshi Emperor against sending the Prince of Xiao north to campaign—I truly know my guilt is deep and dare not surrender!", idiomatic: "Wei said, \"When the Grand Master of Works was killed, I joined in the plot, and I also remonstrated with the Gengshi Emperor against sending the Prince of Xiao north to campaign—I know my guilt is deep and dare not surrender!\"" },
  { zh: "」彭還，具言於帝。", literal: "\" Peng returned and reported fully to the Emperor.", idiomatic: "\" Peng returned and reported fully to the Emperor." },
  { zh: "帝曰：「舉大事者不忌小怨。", literal: "The Emperor said: \"One who undertakes a great enterprise does not heed small resentments.", idiomatic: "The Emperor said, \"One who undertakes a great enterprise does not heed small resentments." },
  { zh: "鮪今若降，官爵可保，況誅罰乎！", literal: "If Wei now surrenders, rank and title can be preserved—how much more so punishment!", idiomatic: "If Wei now surrenders, rank and title can be preserved—how much more punishment!\"" },
  { zh: "河水在此，吾不食言！", literal: "The Yellow River is here—I will not eat my words!", idiomatic: "The Yellow River is here—I will not break my word!\"" },
  { zh: "」彭復往告鮪，鮪從城上下索曰：「必信，可乘此上。", literal: "\" Peng went again to tell Wei; Wei let a rope down from the wall, saying: \"If you are truly to be trusted, you may ascend by this.", idiomatic: "\" Peng went again to tell Wei; Wei let a rope down from the wall and said, \"If you are truly to be trusted, you may ascend by this.\"" },
  { zh: "」彭趣索欲上，鮪見其誠，即許降。", literal: "\" Peng hastened to seize the rope and was about to climb; Wei, seeing his sincerity, at once agreed to surrender.", idiomatic: "\" Peng hastened to seize the rope and climb; Wei, seeing his sincerity, at once agreed to surrender." },
  { zh: "辛卯，朱鮪面縛，與岑彭俱詣河陽。", literal: "On xinmao Zhu Wei came with his face bound and, together with Cen Peng, went to Heyang.", idiomatic: "On xinmao Zhu Wei came with his face bound and, together with Cen Peng, went to Heyang." },
  { zh: "帝解其縛，召見之，復令彭夜送鮪歸城。", literal: "The Emperor undid his bonds, summoned and received him, and again ordered Peng to escort Wei back to the city by night.", idiomatic: "The Emperor undid his bonds, summoned and received him, and again ordered Peng to escort Wei back to the city by night." },
  { zh: "明旦，與蘇茂等悉其眾出降。", literal: "At dawn the next day he and Su Mao and the others led out all their hosts to surrender.", idiomatic: "At dawn the next day he and Su Mao and the others led out all their forces to surrender." },
  { zh: "拜鮪為平狄將軍，封扶溝侯；", literal: "Wei was appointed Pacify-the-Di General and enfeoffed as Marquis of Fugou;", idiomatic: "Wei was appointed Pacify-the-Di General and enfeoffed as Marquis of Fugou;" },
  { zh: "後為少府，傳封累世。", literal: "later he became Minister Steward, and the fief was transmitted through generations.", idiomatic: "later he became Minister Steward, and the fief was transmitted through generations." },
  { zh: "帝使侍御史河內杜詩安集洛陽。", literal: "The Emperor sent Attendant Censor Du Shi of Henei to settle and gather Luoyang.", idiomatic: "The Emperor sent Attendant Censor Du Shi of Henei to settle and pacify Luoyang." },
  { zh: "將軍蕭廣縱兵士暴橫，詩敕曉不改，遂格殺廣。", literal: "General Xiao Guang let his soldiers run violent and overbearing; Shi admonished and instructed him but he did not reform, and Shi thereupon killed Guang on the spot.", idiomatic: "General Xiao Guang let his soldiers run violent and overbearing; Shi admonished him but he did not reform, and Shi thereupon killed Guang on the spot." },
  { zh: "還，以狀聞。", literal: "On returning, he reported the matter in a memorial.", idiomatic: "On returning, he reported the matter in a memorial." },
  { zh: "上召見，賜以棨戟，遂擢任之。", literal: "The sovereign summoned him, bestowed upon him a ceremonial halberd, and thereupon promoted and employed him.", idiomatic: "The sovereign summoned him, bestowed a ceremonial halberd upon him, and thereupon promoted and employed him." },
  { zh: "冬，十月，癸丑，車駕入洛陽，幸南宮，遂定都焉。", literal: "In winter, the tenth month, on guichou, the imperial carriage entered Luoyang, visited the Southern Palace, and thereupon fixed the capital.", idiomatic: "In winter, the tenth month, on guichou, the imperial carriage entered Luoyang, visited the Southern Palace, and thereupon made it the capital." },
  { zh: "16赤眉下書曰：「聖公降者，封為長沙王；", literal: "16. The Chimei issued a document, saying: \"If the Sacred Lord surrenders, he shall be enfeoffed as King of Changsha;", idiomatic: "16. The Chimei issued a document, saying, \"If the Sacred Lord surrenders, he shall be enfeoffed as King of Changsha;" },
  { zh: "過二十日，勿受。", literal: "after twenty days pass, he will not be accepted.", idiomatic: "after twenty days pass, he will not be accepted.\"" },
  { zh: "」更始遣劉恭請降，赤眉使其將謝祿往受之。", literal: "\" The Gengshi Emperor sent Liu Gong to request surrender; the Chimei sent their general Xie Lu to receive him.", idiomatic: "\" The Gengshi Emperor sent Liu Gong to request surrender; the Chimei sent their general Xie Lu to receive him." },
  { zh: "更始隨祿，肉袒，上璽綬於盆子。", literal: "The Gengshi Emperor followed Lu, bared his torso, and presented the seal and cord to Penzi.", idiomatic: "The Gengshi Emperor followed Lu, bared his torso, and presented the seal and cord to Penzi." },
  { zh: "赤眉坐更始，置庭中，將殺之；", literal: "The Chimei seated the Gengshi Emperor, placed him in the courtyard, and were about to kill him;", idiomatic: "The Chimei seated the Gengshi Emperor in the courtyard and were about to kill him;" },
  { zh: "劉恭、謝祿為請，不能得，遂引更始出。", literal: "Liu Gong and Xie Lu pleaded for him but could not prevail, and thereupon led the Gengshi Emperor out.", idiomatic: "Liu Gong and Xie Lu pleaded for him but could not prevail, and thereupon led the Gengshi Emperor out." },
  { zh: "劉恭追呼曰：「臣誠力極，請得先死！", literal: "Liu Gong ran after them calling: \"Your servant has truly exhausted his strength—may I be allowed to die first!", idiomatic: "Liu Gong ran after them calling, \"Your servant has truly exhausted his strength—may I be allowed to die first!\"" },
  { zh: "」拔劍欲自刎。", literal: "\" He drew his sword intending to kill himself.", idiomatic: "\" He drew his sword intending to kill himself." },
  { zh: "樊崇等遽共救止之。", literal: "Fan Chong and the others hastily together rescued and stopped him.", idiomatic: "Fan Chong and the others hastily rescued and stopped him." },
  { zh: "乃赦更始，封為畏威侯。", literal: "They then pardoned the Gengshi Emperor and enfeoffed him as Marquis Who Fears Authority.", idiomatic: "They then pardoned the Gengshi Emperor and enfeoffed him as Marquis Who Fears Authority." },
  { zh: "劉恭復為固請，竟得封長沙王。", literal: "Liu Gong again firmly pleaded, and in the end he was enfeoffed as King of Changsha.", idiomatic: "Liu Gong pleaded again firmly, and in the end he was enfeoffed as King of Changsha." },
  { zh: "更始常依謝祿居，劉恭亦擁護之。", literal: "The Gengshi Emperor regularly lodged with Xie Lu, and Liu Gong also protected and supported him.", idiomatic: "The Gengshi Emperor regularly lodged with Xie Lu, and Liu Gong also protected and supported him." },
  { zh: "17劉盆子居長樂宮，三輔郡縣、營長遣使貢獻，兵士輒剽奪之，又數暴掠吏民，由是皆復固守。", literal: "17. Liu Penzi dwelt in Changle Palace; commanderies and counties of the Three Metropolises and camp chiefs sent envoys with tribute, but the soldiers repeatedly plundered it, and again and again violently looted officials and commoners—whereupon all again held firm in defense.", idiomatic: "17. Liu Penzi dwelt in Changle Palace; commanderies and counties of the Three Metropolises and camp chiefs sent envoys with tribute, but the soldiers repeatedly plundered it and again and again violently looted officials and commoners—whereupon all again held firm in defense." },
  { zh: "百姓不知所歸，聞鄧禹乘勝獨克而師行有紀，皆望風相攜負以迎軍，降者日以千數，眾號百萬。", literal: "The common people did not know where to turn; hearing that Deng Yu, riding victory and advancing alone, had discipline in his army's march, they all at the mere report of wind carried one another on their backs to welcome the army—those surrendering numbered thousands daily, and the host was styled a million.", idiomatic: "The common people did not know where to turn; hearing that Deng Yu, riding victory and advancing alone, kept discipline in his army's march, they all at the mere report of his approach carried one another on their backs to welcome the army—surrenders numbered thousands daily, and the host was styled a million." },
  { zh: "禹所止，輒停車拄節以勞來之，父老、童稚，垂發、戴白滿其車下，莫不感悅，於是名震關西。", literal: "Wherever Yu halted, he would stop his carriage, lean on his staff, and comfort and welcome them; elders and children, hair hanging down and heads white, filled the area beneath his carriage—none failed to be moved and pleased; thereby his fame shook Guanxi.", idiomatic: "Wherever Yu halted, he would stop his carriage, lean on his staff, and comfort and welcome them; elders and children, with hanging hair and white heads, filled the area beneath his carriage—none failed to be moved and pleased; thereby his fame shook Guanxi." },
  { zh: "諸將豪傑皆勸禹徑攻長安，禹曰：「不然。", literal: "The various generals and heroes all urged Yu to strike straight at Chang'an; Yu said: \"It is not so.", idiomatic: "The various generals and heroes all urged Yu to strike straight at Chang'an; Yu said, \"It is not so." },
  { zh: "今吾眾雖多，能戰者少，前無可仰之積，後無轉饋之資；", literal: "Now though our host is many, those who can fight are few; ahead there is no accumulated store to rely on, behind no resources for turning and supplying;", idiomatic: "Now though our host is many, those who can fight are few; ahead there is no accumulated store to rely on, behind no resources for turning and supplying;" },
  { zh: "赤眉新拔長安，財穀充實，鋒銳未可當也。", literal: "the Chimei have newly taken Chang'an; wealth and grain are full, and their sharp edge cannot yet be faced.", idiomatic: "the Chimei have newly taken Chang'an; wealth and grain are full, and their sharp edge cannot yet be faced." },
  { zh: "夫盜賊群居無終日之計，財穀雖多，變故萬端，寧能堅守者也！", literal: "Bandits dwelling in a mass have no plan for a full day; though wealth and grain are many, changes and turns are myriad—how could they hold firm for long!", idiomatic: "Bandits dwelling in a mass have no plan for a full day; though wealth and grain are many, changes are myriad—how could they hold firm for long!\"" },
  { zh: "上郡、北地、安定三郡，土廣人稀，饒穀多畜，吾且休兵北道，就糧養士，以觀其敝，乃可圖也。", literal: "Shang, Beidi, and Anding—the three commanderies—have broad land and sparse people, abundant grain and many livestock; I shall for now rest the troops on the northern road, draw near grain to nourish the soldiers, watch for their exhaustion, and then it may be plotted.", idiomatic: "Shang, Beidi, and Anding—the three commanderies—have broad land and sparse people, abundant grain and many livestock; I shall for now rest the troops on the northern road, draw on grain to nourish the soldiers, watch for their exhaustion, and then we may act.\"" },
  { zh: "」於是引軍北至栒邑，所到，諸營保郡邑皆開門歸附。", literal: "\" Thereupon he led the army north to Xunyi; wherever he arrived, the various fortified camps, commanderies, and counties all opened their gates and submitted.", idiomatic: "\" Thereupon he led the army north to Xunyi; wherever he arrived, fortified camps, commanderies, and counties all opened their gates and submitted." },
  { zh: "18上遣岑彭擊荊州群賊，下犨、葉等十餘城。", literal: "18. The Emperor sent Cen Peng to attack the bandit hosts of Jingzhou and took more than ten cities including Zuan and Ye.", idiomatic: "18. The Emperor sent Cen Peng to attack the bandit hosts of Jingzhou and took more than ten cities including Zuan and Ye." },
  { zh: "19十一月，甲午，上幸懷。", literal: "19. In the eleventh month, on jiawu, the Emperor visited Huai.", idiomatic: "19. In the eleventh month, on jiawu, the Emperor visited Huai." },
  { zh: "20梁王永稱帝於睢陽。", literal: "20. Liu Yong of Liang again declared himself emperor at Suiyang.", idiomatic: "20. Liu Yong of Liang again declared himself emperor at Suiyang." },
  { zh: "21十二月，丙戌<ref>丙戌十二月乙未朔，無丙戌日。", literal: "21. In the twelfth month, on bingxu<ref>On bingxu in the twelfth month—the first day is yiyi; there is no day bingxu.", idiomatic: "21. In the twelfth month, on bingxu<ref>On bingxu in the twelfth month—the first day is yiyi; there is no day bingxu." },
  { zh: "范《書》同</ref>，上還洛陽。", literal: "Fan Ye's History agrees</ref>, and the Emperor returned to Luoyang.", idiomatic: "Fan Ye's History agrees</ref>, and the Emperor returned to Luoyang." },
  { zh: "22三輔苦赤眉暴虐，皆憐更始，欲盜出之；", literal: "22. The Three Metropolises suffered under Chimei violence and tyranny; all pitied the Gengshi Emperor and wished to steal him out;", idiomatic: "22. The Three Metropolises suffered under Chimei violence and tyranny; all pitied the Gengshi Emperor and wished to steal him out;" },
  { zh: "張卬等深以為慮，使謝祿縊殺之。", literal: "Zhang Yin and others were deeply troubled by this and had Xie Lu strangle him to death.", idiomatic: "Zhang Yin and others were deeply troubled by this and had Xie Lu strangle him to death." },
  { zh: "劉恭夜往，收藏其屍。", literal: "Liu Gong went by night, gathered and stored his corpse.", idiomatic: "Liu Gong went by night and gathered and stored his corpse." },
  { zh: "帝詔鄧禹葬之於霸陵。", literal: "The Emperor ordered Deng Yu to bury him at Baling.", idiomatic: "The Emperor ordered Deng Yu to bury him at Baling." },
  { zh: "中郎將宛人趙熹將出武關，道遇更始親屬，皆裸跣饑困，熹竭其資糧以與之，將護而前。", literal: "Gentleman of the Palace Zhao Xi of Wan was about to go out through Wuguan; on the road he met the Gengshi Emperor's kin—all barefoot, hungry, and in distress; Xi exhausted his funds and grain to give them and escorted them forward.", idiomatic: "Gentleman of the Palace Zhao Xi of Wan was about to go out through Wuguan; on the road he met the Gengshi Emperor's kin—all barefoot, hungry, and in distress; Xi exhausted his funds and grain to give them and escorted them forward." },
  { zh: "宛王賜聞之，迎還鄉里。", literal: "The King of Wan, Liu Ci, heard of it and welcomed them back to their native district.", idiomatic: "The King of Wan, Liu Ci, heard of it and welcomed them back to their native district." },
  { zh: "23隗囂歸天水，復招聚其眾，興修故業，自稱西州上將軍。", literal: "23. Wei Ao returned to Tianshui, again gathered his hosts, revived his former enterprise, and styled himself Supreme General of the Western Provinces.", idiomatic: "23. Wei Ao returned to Tianshui, again gathered his forces, revived his former enterprise, and styled himself Supreme General of the Western Provinces." },
  { zh: "三輔士大夫避亂者多歸囂，囂傾身引接，為布衣交；", literal: "Many scholar-officials of the Three Metropolises fleeing disorder came to Ao; Ao bent his person to receive them and made plain-cloth friendships;", idiomatic: "Many scholar-officials of the Three Metropolises fleeing disorder came to Ao; Ao bent his person to receive them and made plain friendships;" },
  { zh: "以平陵范逡為師友，前涼州刺史河內鄭興為祭酒<ref>前涼州刺史河內鄭興為祭酒章校「十二行本『內』作『南』；", literal: "he made Fan Xun of Pingling Friend and Teacher, and Zheng Xing of Henei, former Governor of Former Liang, Libationer<ref>On “former Governor of Former Liang Zheng Xing of Henei as Libationer”—Zhang’s collation: the twelve-line edition reads “south” for “inner”;", idiomatic: "he made Fan Xun of Pingling Friend and Teacher, and Zheng Xing of Henei, former Governor of Former Liang, Libationer<ref>On “former Governor of Former Liang Zheng Xing of Henei as Libationer”: Zhang’s collation—the twelve-line edition reads “south” for “inner”;" },
  { zh: "乙十一行本同；", literal: "the Yi eleven-line edition agrees;", idiomatic: "the Yi eleven-line edition agrees;" },
  { zh: "孔本同。", literal: "Kong’s edition agrees.", idiomatic: "Kong’s edition agrees." },
  { zh: "」未知誰是，今不改。", literal: "” which is correct is unknown; the text is not changed.", idiomatic: "” which is correct is unknown; the text is not changed." },
  { zh: "</ref>，茂陵申屠剛、杜林為治書，馬援為綏德將軍，楊廣、王遵、周宗及平襄行巡、阿陽王捷、長陵王元為大將軍，安陵班彪之屬為賓客，由此名震西州，聞於山東。", literal: "</ref>, Maoling's Shentu Gang and Du Lin as Directors of Documents, Ma Yuan as Pacify-Virtue General, Yang Guang, Wang Zun, Zhou Zong, and Pingxiang's Xing Xun, Ayang's Wang Jie, and Changling's Wang Yuan as great generals, Anling's Ban Biao and his kind as retainers—thereby his fame shook the Western Provinces and was heard in Shandong.", idiomatic: "</ref>, Maoling's Shentu Gang and Du Lin as Directors of Documents, Ma Yuan as Pacify-Virtue General, Yang Guang, Wang Zun, Zhou Zong, and Pingxiang's Xing Xun, Ayang's Wang Jie, and Changling's Wang Yuan as great generals, Anling's Ban Biao and his kind as retainers—thereby his fame shook the Western Provinces and was heard in Shandong." },
  { zh: "馬援少時，以家用不足辭其兄況，欲就邊郡田牧。", literal: "When Ma Yuan was young, because the household was short he took leave of his elder brother Kuang and wished to go to a frontier commandery for farming and herding.", idiomatic: "When Ma Yuan was young, because the household was short he took leave of his elder brother Kuang and wished to go to a frontier commandery for farming and herding." },
  { zh: "況曰：「汝大才，當晚成。", literal: "Kuang said: \"You have great talent and ought to mature late.", idiomatic: "Kuang said, \"You have great talent and ought to mature late." },
  { zh: "良工不示人以朴，且從所好。", literal: "A skilled craftsman does not show people the raw timber—go for now as you wish.", idiomatic: "A skilled craftsman does not show people the raw timber—go for now as you wish.\"" },
  { zh: "」遂之北地田牧。", literal: "\" He thereupon went to Beidi for farming and herding.", idiomatic: "\" He thereupon went to Beidi for farming and herding." },
  { zh: "常謂賓客曰：「丈夫為志，窮當益堅，老當益壯。", literal: "He often told his guests: \"A man in setting his aim—when poor ought to grow firmer, when old ought to grow stronger.", idiomatic: "He often told his guests, \"A man in setting his aim—when poor ought to grow firmer, when old ought to grow stronger.\"" },
  { zh: "」後有畜數千頭，穀數萬斛，既而歎曰：「凡殖財產，貴其能賑施也，否則守錢虜耳！", literal: "\" Later he had several thousand head of livestock and tens of thousands of hu of grain; then he sighed and said: \"In general, amassing property is prized for the ability to relieve and give; otherwise one is merely a money-guarding bondsman!", idiomatic: "\" Later he had several thousand head of livestock and tens of thousands of hu of grain; then he sighed and said, \"In general, amassing property is prized for the ability to relieve and give; otherwise one is merely a money-guarding bondsman!\"" },
  { zh: "」乃盡散於親舊。", literal: "\" He then distributed it all among kin and old friends.", idiomatic: "\" He then distributed it all among kin and old friends." },
  { zh: "聞隗囂好士，往從之。", literal: "Hearing that Wei Ao loved scholars, he went to join him.", idiomatic: "Hearing that Wei Ao loved scholars, he went to join him." },
  { zh: "囂其敬重，與決籌策。", literal: "Ao greatly respected him and settled plans and stratagems with him.", idiomatic: "Ao greatly respected him and settled plans and stratagems with him." },
  { zh: "班彪，稚之子也。", literal: "Ban Biao was the son of Zhi.", idiomatic: "Ban Biao was the son of Zhi." },
  { zh: "24初，平陵竇融累世仕宦河西，知其土俗，與更始右大司馬趙萌善，私謂兄弟曰：「天下安危未可知。", literal: "24. Earlier, Pingling's Dou Rong's family for generations served as officials in Hexi and knew its local customs; he was on good terms with the Gengshi Emperor's Right Grand Master of Works Zhao Meng and privately told his brothers: \"The realm's safety or peril cannot yet be known.", idiomatic: "24. Earlier, Pingling's Dou Rong's family had for generations served as officials in Hexi and knew its local customs; he was on good terms with the Gengshi Emperor's Right Grand Master of Works Zhao Meng and privately told his brothers, \"The realm's safety or peril cannot yet be known." },
  { zh: "河西殷富，帶河為固，張掖屬國精兵萬騎，一旦緩急，杜絕河津，足以自守，此遺種處也！", literal: "Hexi is rich and prosperous, girded by the river and secure; Zhangye Dependent State has ten thousand crack horsemen—if urgency comes, block the river crossings and it is enough for self-defense—this is a place to preserve one's line!", idiomatic: "Hexi is rich and prosperous, girded by the river and secure; Zhangye Dependent State has ten thousand crack horsemen—if urgency comes, block the river crossings and it is enough for self-defense—this is a place to preserve one's line!\"" },
  { zh: "」乃因萌求往河西。", literal: "\" He thereupon through Meng requested to go to Hexi.", idiomatic: "\" He thereupon through Meng requested to go to Hexi." },
  { zh: "萌薦融於更始，以為張掖屬國都尉。", literal: "Meng recommended Rong to the Gengshi Emperor, and he was made Commandant of Zhangye Dependent State.", idiomatic: "Meng recommended Rong to the Gengshi Emperor, and he was made Commandant of Zhangye Dependent State." },
  { zh: "融既到，撫結雄桀，懷輯羌虜，甚得其歡心。", literal: "Once Rong had arrived, he soothed and bound bold champions, embraced and gathered Qiang and barbarians—he won their hearts exceedingly.", idiomatic: "Once Rong had arrived, he soothed and bound bold champions, won over the Qiang and other tribes, and gained their hearts completely." },
  { zh: "是時，酒泉太守安定梁統、金城太守庫鈞、張掖都尉茂陵史苞、酒泉都尉竺曾、敦煌都尉辛肜，并州郡英俊，融皆與厚善。", literal: "At that time Jiuquan Administrator Anding Liang Tong, Jincheng Administrator Ku Jun, Zhangye Commandant Maoling Shi Bao, Jiuquan Commandant Zhu Ceng, Dunhuang Commandant Xin Yin—all commandery talents of Bing—Rong was on close terms with them all.", idiomatic: "At that time Jiuquan Administrator Liang Tong of Anding, Jincheng Administrator Ku Jun, Zhangye Commandant Shi Bao of Maoling, Jiuquan Commandant Zhu Ceng, and Dunhuang Commandant Xin Yin were all outstanding men of the Bing region, and Rong was on close terms with every one of them." },
  { zh: "及更始敗，融與梁統等計議曰：「今天下擾亂，未知所歸。", literal: "When Gengshi fell, Rong with Liang Tong and others deliberated: \"Now the realm is disturbed—no one knows where to turn.", idiomatic: "When Gengshi fell, Rong deliberated with Liang Tong and others, saying, \"The realm is in turmoil and no one knows where to turn." },
  { zh: "河西斗絕在羌、胡中，不同心戮力，則不能自守，權鈞力齊，復無以相率，當推一人為大將軍，共全五部，觀時變動。", literal: "Hexi stands alone amid Qiang and Hu—without one heart and joined strength we cannot hold ourselves; powers equal and forces matched, again none can lead the rest—we should push one man as grand general, jointly preserve the five commanderies, and watch how the times change.", idiomatic: "Hexi stands isolated among the Qiang and Hu; unless we unite in heart and strength we cannot hold our ground, and with powers and forces evenly matched none can lead the rest. We should choose one man as grand general, jointly preserve the five commanderies, and watch how the times change.\"" },
  { zh: "」議既定，而各謙讓。", literal: "\" Once the plan was settled, each demurred.", idiomatic: "\" Once the plan was settled, each man demurred." },
  { zh: "以位次，咸共推梁統；", literal: "By rank in office, all together pushed Liang Tong;", idiomatic: "By rank in office, all together pushed Liang Tong;" },
  { zh: "統固辭，乃推融行河西五郡大將軍事。", literal: "Tong firmly declined, and they then pushed Rong to act as grand general over Hexi's five commanderies.", idiomatic: "Tong firmly declined, and they then pushed Rong to act as grand general over Hexi's five commanderies." },
  { zh: "武威太守馬期、張掖太守任仲並孤立無黨，乃共移書告示之，二人即解印綬去。", literal: "Wuwei Administrator Ma Qi and Zhangye Administrator Ren Zhong were both isolated without factions; they jointly sent a letter to announce this—the two at once surrendered seal and cord and left.", idiomatic: "Wuwei Administrator Ma Qi and Zhangye Administrator Ren Zhong were both isolated without factions; they jointly sent a proclamation to them, and the two at once surrendered their seals and cords and departed." },
  { zh: "於是以梁統為武威太守，史苞為張掖太守，竺曾為酒泉太守，辛肜為敦煌太守。", literal: "Thereupon Liang Tong was made Wuwei Administrator, Shi Bao Zhangye Administrator, Zhu Ceng Jiuquan Administrator, Xin Yin Dunhuang Administrator.", idiomatic: "Thereupon Liang Tong was made Wuwei Administrator, Shi Bao Zhangye Administrator, Zhu Ceng Jiuquan Administrator, and Xin Yin Dunhuang Administrator." },
  { zh: "融居屬國，領都尉職如故；", literal: "Rong remained in the dependent state, holding commandant duties as before;", idiomatic: "Rong remained in the dependent state and held his commandant's duties as before;" },
  { zh: "置從事，監察五郡。", literal: "he appointed attendants to oversee the five commanderies.", idiomatic: "he appointed attendants to oversee the five commanderies." },
  { zh: "河西民俗質樸，而融等政亦寬和，上下相親，晏然富殖。", literal: "Hexi's customs were plain and simple, and Rong and the others' government was also lenient and mild—superiors and inferiors were close, and in peace they grew rich.", idiomatic: "Hexi's people were plain by custom, and Rong and the others governed leniently and mildly; superiors and inferiors drew close, and in peace the region grew prosperous." },
  { zh: "修兵馬，習戰射，明烽燧，羌、胡犯塞，融輒自將與諸郡相救，皆如符要，每輒破之。", literal: "They trained horses and arms, practiced battle and archery, made beacon fires clear—when Qiang and Hu raided the passes Rong always led in person with the commanderies to rescue; all matched the tally and tally-string, and each time he broke them.", idiomatic: "They trained horses and arms, practiced battle and archery, and kept the beacon fires clear; whenever the Qiang and Hu raided the passes Rong always led in person with the commanderies to the rescue, every move matched the plan, and each time he routed them." },
  { zh: "其後羌、胡皆震服親附，內郡流民避凶饑者歸之不絕。", literal: "Afterward Qiang and Hu were all awed into submission and drew near; refugees from inner commanderies fleeing disaster and famine came to them without cease.", idiomatic: "Afterward the Qiang and Hu were all awed into submission and drew near, and refugees from the inner commanderies fleeing disaster and famine came to them without cease." },
  { zh: "25王莽之世，天下咸思漢德，安定三水盧芳居左谷中，詐稱武帝曾孫劉文伯，云「曾祖母，匈奴渾邪王之姊也」。", literal: "25. In Wang Mang's age the realm all longed for Han's virtue; Anding's Sanshui Lu Fang dwelt in Zuogu valley, falsely styled himself Emperor Wu's great-grandson Liu Wenbo, saying \"My great-grandmother was sister to the Xiongnu King who Surrendered with Good Faith.\"", idiomatic: "25. In Wang Mang's age the realm all longed for Han's virtue; Lu Fang of Sanshui in Anding dwelt in Zuogu valley, falsely styled himself Emperor Wu's great-grandson Liu Wenbo, and said, \"My great-grandmother was sister to the Xiongnu King who Surrendered with Good Faith.\"" },
  { zh: "常以是言誑惑安定間。", literal: "He constantly used this speech to deceive those in Anding.", idiomatic: "He constantly used this tale to deceive the people of Anding." },
  { zh: "王莽末，乃與三水屬國羌、胡起兵。", literal: "At Wang Mang's end he then with Sanshui dependent state's Qiang and Hu raised troops.", idiomatic: "At the end of Wang Mang's reign he raised troops with the Qiang and Hu of the Sanshui dependent state." },
  { zh: "更始至長安，征芳為騎都尉，使鎮撫安定以西。", literal: "When Gengshi reached Chang'an he summoned Fang as Cavalry Commandant and sent him to pacify Anding and west.", idiomatic: "When Gengshi reached Chang'an he summoned Fang as Cavalry Commandant and sent him to pacify Anding and the region west of it." },
  { zh: "更始敗，三水豪桀共立芳為上將軍、西平王，使使與西羌、匈奴結和親。", literal: "When Gengshi fell, Sanshui's bold leaders together enthroned Fang as Grand General and King Who Pacifies the West, and sent envoys to ally in marriage with Western Qiang and the Xiongnu.", idiomatic: "When Gengshi fell, the bold leaders of Sanshui together enthroned Fang as Grand General and King Who Pacifies the West and sent envoys to ally in marriage with the Western Qiang and the Xiongnu." },
  { zh: "單于以為：「漢氏中絕，劉氏來歸，我亦當如呼韓邪立之，令尊事我。", literal: "The chanyu thought: \"Han is cut off in the middle; the Liu house has come to submit—I too should establish him as with Huhanye, and have him honor and serve me.", idiomatic: "The chanyu thought, \"Han is cut off in the middle; the Liu house has come to submit—I too should establish him as I did Huhanye and have him honor and serve me.\"" },
  { zh: "」乃使句林王將數千騎迎芳兄弟入匈奴，立芳為漢帝，以芳弟程為中郎將，將胡騎還入安定。", literal: "\" He then sent the King of Goulin with several thousand horsemen to welcome Fang and his brothers into the Xiongnu, enthroned Fang as Han Emperor, made Fang's younger brother Cheng Central Palace Gentleman, and led Hu cavalry back into Anding.", idiomatic: "\" He then sent the King of Goulin with several thousand horsemen to welcome Fang and his brothers into the Xiongnu, enthroned Fang as Han Emperor, made Fang's younger brother Cheng Central Palace Gentleman, and led Xiongnu cavalry back into Anding." },
  { zh: "26帝以關中未定，而鄧禹久不進兵，賜書責之曰：「司徒，堯也；", literal: "26. The Emperor because Guanzhong was not settled and Deng Yu long did not advance troops, granted a letter reproaching him: \"Minister of the Masses is Yao;", idiomatic: "26. Because Guanzhong was not yet settled and Deng Yu had long failed to advance, the Emperor sent him a letter of reproach, saying, \"The Minister of the Masses is Yao;" },
  { zh: "亡賊，桀也。", literal: "the perished bandits are Jie.", idiomatic: "the doomed bandits are Jie." },
  { zh: "長安吏民遑遑無所依歸，宜以時進討，鎮慰西京，繫百姓之心。", literal: "Chang'an's officials and people are anxious with nowhere to rely—you should advance and campaign in season, pacify and comfort the western capital, and bind the hundred surnames' hearts.", idiomatic: "Chang'an's officials and people are anxious with nowhere to turn; you should advance and campaign in season, pacify and comfort the western capital, and bind the people's hearts.\"" },
  { zh: "」禹猶執前意，別攻上郡諸縣，更徵兵引穀，歸至大要。", literal: "\" Yu still held to his former intent, separately attacked Shang commandery's counties, again levied troops and drew grain, and returned to Dayao.", idiomatic: "\" Yu still held to his former plan, separately attacked the counties of Shang commandery, again levied troops and drew grain, and returned to Dayao." },
  { zh: "積弩將軍馮愔、車騎將軍宗歆守栒邑，二人爭權相攻，愔遂殺歆，因反擊禹，禹遣使以聞。", literal: "Stacked-crossbow General Feng Yin and Chariots-and-Cavalry General Zong Xin guarded Xunyi; the two contended for power and attacked each other—Yin then killed Xin and turned to strike Yu; Yu sent an envoy to report.", idiomatic: "Stacked-Crossbow General Feng Yin and Chariots-and-Cavalry General Zong Xin guarded Xunyi; the two fought over power, Yin killed Xin, and turned to strike Yu; Yu sent an envoy to report it." },
  { zh: "帝問使人：「愔所親愛為誰？", literal: "The Emperor asked the envoy: \"Whom does Yin love and favor?", idiomatic: "The Emperor asked the envoy, \"Whom does Yin love and favor?" },
  { zh: "」對曰：「護軍黃防。", literal: "\" He answered: \"Protector of the Army Huang Fang.\"", idiomatic: "\" He answered, \"Protector of the Army Huang Fang.\"" },
  { zh: "」帝度愔、防不能久和，勢必相忤，因報禹曰：「縛馮愔者，必黃防也。", literal: "\" The Emperor reckoned Yin and Fang could not long be at peace and would surely clash, and therefore replied to Yu: \"Whoever binds Feng Yin will surely be Huang Fang.\"", idiomatic: "\" The Emperor reckoned Yin and Fang could not long remain at peace and would surely clash, and therefore replied to Yu, \"Whoever binds Feng Yin will surely be Huang Fang.\"" },
  { zh: "」乃遣尚書宗廣持節往降之。", literal: "\" He then sent Masters of Writing Zong Guang bearing credentials to go and accept their surrender.", idiomatic: "\" He then sent Masters of Writing Zong Guang bearing credentials to go and accept their surrender." },
  { zh: "後月餘，防果執愔，將其眾歸罪。", literal: "More than a month later Fang indeed seized Yin and led his host back to answer for the crime.", idiomatic: "More than a month later Fang indeed seized Yin and led his troops back to answer for the crime." },
  { zh: "更始諸將王匡、胡殷、成丹等皆詣廣降，廣與東歸；", literal: "Gengshi's generals Wang Kuang, Hu Yin, Cheng Dan and others all came to Guang to surrender; Guang went east with them;", idiomatic: "Gengshi's generals Wang Kuang, Hu Yin, Cheng Dan, and others all came to Guang to surrender, and Guang went east with them;" },
  { zh: "至安邑，道欲亡，廣悉斬之。", literal: "reaching Anyi, on the road they wished to flee—Guang beheaded them all.", idiomatic: "at Anyi they wished to flee on the road, and Guang beheaded them all." },
  { zh: "愔之叛也，引兵西向天水；", literal: "When Yin rebelled he led troops west toward Tianshui;", idiomatic: "When Yin rebelled he led troops west toward Tianshui;" },
  { zh: "隗囂逆擊，破之於高平，盡獲其輜重。", literal: "Wei Xiao met and struck him, broke him at Gaoping, and took all his baggage train.", idiomatic: "Wei Xiao met and struck him, routed him at Gaoping, and took all his baggage train." },
  { zh: "於是禹承製遣使持節命囂為西州大將軍，得專制涼州、朔方事。", literal: "Thereupon Yu, acting on the imperial edict, sent an envoy bearing credentials to appoint Xiao Western Province Grand General, with full discretion over Liang and Shuofang affairs.", idiomatic: "Thereupon Yu, acting on the imperial edict, sent an envoy bearing credentials to appoint Xiao Western Province Grand General with full discretion over Liang and Shuofang affairs." },
  { zh: "27臘日，赤眉設樂大會，酒未行，群臣更相辯斗；", literal: "27. On the La festival day the Red Eyebrows set music for a great assembly—before the wine was served the ministers argued and fought one another;", idiomatic: "27. On the La festival day the Red Eyebrows set music for a great assembly; before the wine was served the ministers argued and fought one another;" },
  { zh: "而兵眾遂各逾宮，斬關入，掠酒肉，互相殺傷。", literal: "then the soldiers each crossed the palaces, cut the gates and entered, plundered wine and meat, and killed and wounded one another.", idiomatic: "then the soldiers each stormed the palaces, cut through the gates, plundered wine and meat, and killed and wounded one another." },
  { zh: "衛尉諸葛稚聞之，勒兵入，格殺百餘人，乃定。", literal: "Commandant of the Guard Zhuge Zhi heard it, drew troops in, and killed more than a hundred in the melee—then it was settled.", idiomatic: "Commandant of the Guard Zhuge Zhi heard of it, drew troops in, and killed more than a hundred in the melee before order was restored." },
  { zh: "劉盆子惶恐，日夜啼泣，從官皆憐之。", literal: "Liu Penzi was terrified, weeping day and night; his attendants all pitied him.", idiomatic: "Liu Penzi was terrified and wept day and night; his attendants all pitied him." },
  { zh: "28帝遣宗正劉延攻天井關，與田邑連戰十餘合，延不得進。", literal: "28. The Emperor sent Director of the Imperial Clan Liu Yan to attack Tianjing Pass; with Tian Yi he fought more than ten engagements in succession—Yan could not advance.", idiomatic: "28. The Emperor sent Director of the Imperial Clan Liu Yan to attack Tianjing Pass; he fought more than ten engagements in succession with Tian Yi and could not advance." },
  { zh: "及更始敗，邑遣使請降；", literal: "When Gengshi fell, Yi sent an envoy to request surrender;", idiomatic: "When Gengshi fell, Yi sent an envoy to request surrender;" },
  { zh: "即拜為上黨太守。", literal: "he was at once appointed Shangdang Administrator.", idiomatic: "he was at once appointed Shangdang Administrator." },
  { zh: "帝又遣諫議大夫儲大伯持節徵鮑永；", literal: "The Emperor also sent Remonstrance Grandee Chu Dabo bearing credentials to summon Bao Yong;", idiomatic: "The Emperor also sent Remonstrance Grandee Chu Dabo bearing credentials to summon Bao Yong;" },
  { zh: "永未知更始存亡，疑不肯從，收繫大伯，遣使馳至長安，詗問虛實。", literal: "Yong did not know whether Gengshi lived or perished, suspected and would not follow—he seized and bound Dabo, sent an envoy galloping to Chang'an to inquire the truth.", idiomatic: "Yong did not know whether Gengshi still lived, suspected the summons, and refused to obey; he seized and bound Dabo and sent an envoy galloping to Chang'an to learn the truth." },
  { zh: "29初，帝從更始在宛，納新野陰氏之女麗華。", literal: "29. At first, when the Emperor followed Gengshi at Wan, he took as wife Xinye's Lady Yin Lihua.", idiomatic: "29. At first, when the Emperor followed Gengshi at Wan, he took as wife Lady Yin Lihua of the Yin clan of Xinye." },
  { zh: "是歲，遣使迎麗華與帝姊湖陽公主、妹寧平公主俱到洛陽；", literal: "That year he sent an envoy to welcome Lihua, the Emperor's elder sister the Princess of Huyang, and his younger sister the Princess of Ningping—all together to Luoyang;", idiomatic: "That year he sent an envoy to welcome Lihua, the Emperor's elder sister the Princess of Huyang, and his younger sister the Princess of Ningping, all together to Luoyang;" },
  { zh: "以麗華為貴人。", literal: "he made Lihua Honored Lady.", idiomatic: "he made Lihua Honored Lady." },
  { zh: "更始西平王李通先娶寧平公主，上征通為衛尉。", literal: "Gengshi's King Who Pacifies the West Li Tong had earlier married the Princess of Ningping; the Emperor summoned Tong as Commandant of the Guard.", idiomatic: "Gengshi's King Who Pacifies the West, Li Tong, had earlier married the Princess of Ningping; the Emperor summoned Tong as Commandant of the Guard." },
  { zh: "30初，更始以王閎為琅邪太守，張步據郡拒之。", literal: "30. At first Gengshi made Wang Hong Administrator of Langye; Zhang Bu held the commandery and refused him.", idiomatic: "30. At first Gengshi made Wang Hong Administrator of Langye; Zhang Bu held the commandery and refused him." },
  { zh: "閎諭降，得贛榆等六縣；", literal: "Hong persuaded surrender and got Gan Yu and six other counties;", idiomatic: "Hong persuaded men to surrender and took Gan Yu and six other counties;" },
  { zh: "收兵與步戰，不勝。", literal: "he gathered troops and fought Bu—could not win.", idiomatic: "he gathered troops and fought Bu but could not win." },
  { zh: "步既受劉永官號，治兵於劇，遣將徇泰山、東萊、城陽、膠東、北海、濟南、齊郡，皆下之。", literal: "Bu having received Liu Yong's titles and offices, drilled troops at Ju, sent generals to overrun Taishan, Donglai, Chengyang, Jiaodong, Beihai, Jinan, and Qi commanderies—all were taken.", idiomatic: "Bu, having received Liu Yong's titles and offices, drilled troops at Ju and sent generals to overrun Taishan, Donglai, Chengyang, Jiaodong, Beihai, Jinan, and Qi commandery; all submitted." },
  { zh: "閎力不敵，乃詣步相見。", literal: "Hong's strength could not match him, so he went to Bu to meet face to face.", idiomatic: "Hong could not match his strength and went to meet Bu in person." },
  { zh: "步大陳兵而見之。", literal: "Bu arrayed troops in great force to receive him.", idiomatic: "Bu arrayed a great force of troops to receive him." },
  { zh: "怒曰：「步有何罪，君前見攻之甚！", literal: "Angry, he said: \"What crime has Bu committed, that you earlier attacked me so fiercely!", idiomatic: "Angry, he said, \"What crime has Bu committed, that you earlier attacked me so fiercely!" },
  { zh: "」閎按劍曰：「太守奉朝命，而文公擁兵相拒。", literal: "\" Hong gripped his sword and said: \"The Administrator obeys the court's command, while Lord Wen holds troops and resists.", idiomatic: "\" Hong gripped his sword and said, \"The Administrator obeys the court's command, while Lord Wen holds troops and resists." },
  { zh: "閎攻賊耳，何謂甚邪！", literal: "Hong attacks bandits—what do you call fierce!", idiomatic: "Hong attacks bandits—what do you call fierce!\"" },
  { zh: "」步起跪謝，與之宴飲，待為上賓，令閎關掌郡事。", literal: "\" Bu rose and knelt in apology, feasted and drank with him, treated him as a chief guest, and ordered Hong to oversee the commandery's affairs at the passes.", idiomatic: "\" Bu rose and knelt in apology, feasted with him, treated him as a chief guest, and put Hong in charge of the commandery's affairs at the passes." },
  { zh: "1春，正月，甲子朔，日有食之。", literal: "1. Spring, first month, on the first day jiazi there was an eclipse of the sun.", idiomatic: "1. In spring, the first month, on the first day jiazi there was a solar eclipse." },
  { zh: "2劉恭知赤眉必敗，密教弟盆子歸璽綬，習為辭讓之言。", literal: "2. Liu Gong knew the Red Eyebrows would surely fall; he secretly taught his younger brother Penzi to return seal and cord and practiced words of yielding.", idiomatic: "2. Liu Gong knew the Red Eyebrows would surely fall; he secretly taught his younger brother Penzi to return the seal and cord and practiced words of yielding." },
  { zh: "及正旦大會，恭先曰：「諸君共立恭弟為帝，德誠深厚！", literal: "At the New Year's great assembly Gong spoke first: \"You gentlemen together enthroned Gong's younger brother as emperor—your virtue is truly deep and thick!", idiomatic: "At the New Year's great assembly Gong spoke first, \"You gentlemen together enthroned my younger brother as emperor—your virtue is truly deep and great!" },
  { zh: "立且一年，殽亂日甚，誠不足以相成，恐死而無益，願得退為庶人，更求賢知，唯諸君省察！", literal: "Enthroned nearly a year, chaos grows worse daily—truly not enough to accomplish together; I fear to die without benefit. I wish to withdraw and become a common man, and seek the worthy and wise anew—only let you gentlemen reflect!", idiomatic: "He has reigned nearly a year, yet chaos grows worse daily—truly we cannot accomplish anything together, and I fear to die without benefit. I wish to withdraw and become a common man and seek the worthy and wise anew—only let you gentlemen reflect!\"" },
  { zh: "」樊崇等謝曰：「此者崇等罪也。", literal: "\" Fan Chong and others apologized: \"This is Chong and others' crime.", idiomatic: "\" Fan Chong and others apologized, \"This is Chong and others' crime.\"" },
  { zh: "」恭復固請，或曰：「此寧式侯事邪？", literal: "\" Gong again firmly requested; some said: \"Is this surely the Marquis of Shi's affair?", idiomatic: "\" Gong again firmly requested; some said, \"Is this surely the Marquis of Shi's affair?\"" },
  { zh: "」恭惶恐起去。", literal: "\" Gong in terror rose and left.", idiomatic: "\" Gong rose in terror and left." },
  { zh: "盆子乃下床解璽綬，叩頭曰：「今設置縣官而為賊如故，四方怨恨，不覆信向，此皆立非其人所致。", literal: "Penzi then came down from the bed, unfastened seal and cord, kowtowed and said: \"Now we set up county officials yet act as bandits as before—the four quarters resent it and will not again trust and turn to us; all this comes from enthroning the wrong man.", idiomatic: "Penzi then came down from the bed, unfastened the seal and cord, kowtowed, and said, \"Now we set up county officials yet act as bandits as before—the four quarters resent us and will not trust us again; all this comes from enthroning the wrong man." },
  { zh: "願乞骸骨，避賢聖路！", literal: "I beg to offer my bones and withdraw, clearing the road for the worthy and sage!", idiomatic: "I beg to offer my bones and withdraw, clearing the road for the worthy and sage!" },
  { zh: "必欲殺盆子以塞責者，無所離死！", literal: "If you must kill Penzi to answer for the blame, I have nowhere to flee from death!", idiomatic: "If you must kill Penzi to answer for the blame, I have nowhere to flee from death!\"" },
  { zh: "」因涕泣噓唏。", literal: "\" He then wept and sobbed.", idiomatic: "\" He then wept and sobbed." },
  { zh: "崇等及會者數百人，莫不哀憐之，乃皆避席頓首曰：「臣無狀，負陛下，請自今已後，不敢復放縱！", literal: "Chong and others and those at the assembly, several hundred, none did not pity him in sorrow; they all left their mats and knocked their heads, saying: \"Your subjects are without form, we have failed Your Majesty—from now on we dare not again run wild!", idiomatic: "Chong and the several hundred at the assembly all pitied him; they left their mats and knocked their heads, saying, \"Your subjects have failed Your Majesty—from now on we dare not run wild again!\"" },
  { zh: "」因共抱持盆子，帶以璽綬；", literal: "\" They then together embraced and held Penzi, belted him with seal and cord;", idiomatic: "\" They then together embraced Penzi and belted him with the seal and cord;" },
  { zh: "盆子號呼，不得已。", literal: "Penzi cried out—he could not help it.", idiomatic: "Penzi cried out, unable to refuse." },
  { zh: "既罷出，各閉營自守。", literal: "When the assembly ended and they went out, each closed camp and held himself.", idiomatic: "When the assembly ended they went out, and each closed his camp and held to himself." },
  { zh: "三輔翕然，稱天子聰明，百姓爭還長安，市裡且滿。", literal: "The three adjuncts were united in praise, calling the Son of Heaven clear-sighted; the hundred surnames vied to return to Chang'an, and the markets were nearly full.", idiomatic: "The Three Adjuncts united in praise, calling the Son of Heaven clear-sighted; the people vied to return to Chang'an until the markets were nearly full." },
  { zh: "後二十餘日，復出，大掠如故。", literal: "After more than twenty days they again went out and plundered on a great scale as before.", idiomatic: "After more than twenty days they again went out and plundered on a great scale as before." },
  { zh: "3〔刁〕(", literal: "3. [Diao](", idiomatic: "3. [Diao](" },
  { zh: "刀)", literal: "Dao)", idiomatic: "Dao)" },
  { zh: "子都為其部曲所殺<ref>〔刁〕(", literal: "Zi Du was killed by his own retainers<ref>[Diao](", idiomatic: "Zi Du was killed by his own retainers<ref>[Diao](" },
  { zh: "刀)", literal: "Dao)", idiomatic: "Dao)" },
  { zh: "子都為其部曲所殺據胡注改。", literal: "Zi Du was killed by his own retainers—emended per Hu Zhu's note.", idiomatic: "Zi Du was killed by his own retainers—emended per Hu Zhu's note." },
  { zh: "</ref>，餘黨與諸賊會檀鄉，號檀鄉賊，寇魏郡、清河。", literal: "</ref>, the survivors joined other bandits at Tanxiang, styled themselves Tanxiang bandits, and raided Wei and Qinghe commanderies.", idiomatic: "</ref>; the survivors joined other bandits at Tanxiang, styled themselves the Tanxiang bandits, and raided Wei and Qinghe commanderies." },
  { zh: "魏郡大吏李熊弟陸謀反城迎檀鄉，或以告魏郡太守穎川銚期，期召問熊，熊叩頭首服，願與老母俱就死。", literal: "Wei commandery's chief clerk Li Xiong's younger brother Lu plotted rebellion to open the city and welcome Tanxiang; someone reported it to Wei Administrator Yingchuan Jiao Qi—Qi summoned and questioned Xiong; Xiong knocked his head and confessed first, wishing to go to death together with his old mother.", idiomatic: "Li Xiong, a chief clerk of Wei commandery, had a younger brother Lu who plotted rebellion to open the city to the Tanxiang bandits; someone reported it to Wei Administrator Jiao Qi of Yingchuan; Qi summoned and questioned Xiong; Xiong knocked his head and confessed, wishing to go to death together with his old mother." },
  { zh: "期曰：「為吏儻不若為賊樂者，可歸與老母往就陸也！", literal: "Qi said: \"If serving as clerk is perhaps not as pleasant as serving as bandit, you may return with your old mother and go join Lu!", idiomatic: "Qi said, \"If serving as a clerk is perhaps not as pleasant as serving as a bandit, you may return with your old mother and go join Lu!\"" },
  { zh: "」使吏送出城。", literal: "\" He sent clerks to escort him out of the city.", idiomatic: "\" He sent clerks to escort him out of the city." },
  { zh: "熊行，求得陸，將詣鄴城西門；", literal: "Xiong went, found Lu, and was about to take him to Ye city's west gate;", idiomatic: "Xiong went, found Lu, and was about to take him to Ye's west gate;" },
  { zh: "陸不勝愧感，自殺以謝期。", literal: "Lu could not bear the shame and moved feeling—he killed himself to answer to Qi.", idiomatic: "Lu could not bear the shame and killed himself to answer to Qi." },
  { zh: "期嗟歎，以禮葬之，而還熊故職。", literal: "Qi sighed in admiration, buried him with rites, and restored Xiong to his former post.", idiomatic: "Qi sighed in admiration, buried him with rites, and restored Xiong to his former post." },
  { zh: "於是郡中服其威信。", literal: "Thereupon the commandery submitted to his prestige and authority.", idiomatic: "Thereupon the commandery submitted to his prestige and authority." },
  { zh: "帝遣吳漢率王梁等九將軍擊檀鄉於鄴東漳水上，大破之，十餘萬眾皆降。", literal: "The Emperor sent Wu Han leading Wang Liang and nine other generals to strike the Tanxiang bandits on the Zhang River east of Ye—greatly broke them; a host of more than a hundred thousand all surrendered.", idiomatic: "The Emperor sent Wu Han leading Wang Liang and nine other generals to strike the Tanxiang bandits on the Zhang River east of Ye, routed them utterly, and more than a hundred thousand men all surrendered." },
  { zh: "又使梁與大將軍杜茂將兵安輯魏郡、清河、東郡，悉平諸營保，三郡清靜，邊路流通。", literal: "He also sent Liang with Grand General Du Mao to lead troops and pacify Wei, Qinghe, and Dong commanderies, leveling all fortified camps; the three commanderies were clear and quiet, and the border roads were open.", idiomatic: "He also sent Liang with Grand General Du Mao to lead troops and pacify Wei, Qinghe, and Dong commanderies, leveling all fortified camps; the three commanderies were clear and quiet and the border roads were open." },
  { zh: "4庚辰，悉封諸功臣為列侯；", literal: "4. On gengchen day all the merit ministers were enfeoffed as ranked marquises;", idiomatic: "4. On the day gengchen all the merit ministers were enfeoffed as ranked marquises;" },
  { zh: "梁侯鄧禹、廣平侯吳漢皆食四縣。", literal: "Marquis of Liang Deng Yu and Marquis of Guangping Wu Han each drew revenue from four counties.", idiomatic: "Marquis of Liang Deng Yu and Marquis of Guangping Wu Han each drew revenue from four counties." },
  { zh: "博士丁恭議曰：「古者封諸侯不過百里，強幹弱枝，所以為治也。", literal: "Erudite Ding Gong remonstrated: \"In antiquity enfeoffing feudal lords did not exceed a hundred li—strengthening the trunk and weakening the branches was how to govern.", idiomatic: "Erudite Ding Gong remonstrated, \"In antiquity enfeoffing feudal lords did not exceed a hundred li—strengthening the trunk and weakening the branches was how to govern." },
  { zh: "今封四縣，不合法制。", literal: "Now enfeoffing four counties does not accord with law and regulation.", idiomatic: "Now enfeoffing four counties does not accord with law and regulation.\"" },
  { zh: "」帝曰：「古之亡國皆以無道，未嘗聞功臣地多而滅亡者也。", literal: "\" The Emperor said: \"States of antiquity that perished all did so through lack of the Way—I have never heard of a merit minister perishing because his lands were many.", idiomatic: "\" The Emperor said, \"States of antiquity that perished all did so through lack of the Way—I have never heard of a merit minister perishing because his lands were many.\"" },
  { zh: "」陰鄉侯陰識，貴人之兄也，以軍功當增封，識叩頭讓曰：「天下初定，將帥有功者眾，臣托屬掖廷，仍加爵邑，不可以示天下。", literal: "\" Yinxiang Marquis Yin Shi, the Honored Lady's elder brother, by military merit ought to have his enfeoffment increased; Shi knocked his head and declined: \"The realm is newly settled—generals with merit are many; your subject relies on the palace harem and still receives added rank and fief—this cannot be shown to the realm.", idiomatic: "\" Yinxiang Marquis Yin Shi, the Honored Lady's elder brother, by military merit ought to have his enfeoffment increased; Shi knocked his head and declined, \"The realm is newly settled and many generals have merit; your subject relies on the palace harem and still receives added rank and fief—this cannot be shown to the realm." },
  { zh: "此為親戚受賞，國人計功也。", literal: "This would be kin receiving reward while the state's people reckon merit.", idiomatic: "That would be kin receiving reward while the state's people reckon merit.\"" },
  { zh: "」帝從之。", literal: "\" The Emperor followed his counsel.", idiomatic: "\" The Emperor followed his counsel." },
  { zh: "帝令諸將各言所樂，皆占美縣；", literal: "The Emperor ordered the generals each to state what they preferred—all chose fine counties;", idiomatic: "The Emperor ordered the generals each to state what they preferred, and all chose fine counties;" },
  { zh: "河南太守穎川丁綝獨求封本鄉。", literal: "Grand Administrator of Henan Ding Shen of Yingchuan alone requested enfeoffment in his native district.", idiomatic: "Ding Shen of Yingchuan, Grand Administrator of Henan, alone requested enfeoffment in his native district." },
  { zh: "或問其故，綝曰：「綝能薄功微，得鄉亭厚矣！", literal: "Someone asked the reason; Shen said: \"Shen's ability is slight and merit small—to obtain a township would already be generous!", idiomatic: "When someone asked why, Shen said, \"My ability is slight and my merit small—to obtain even a township would already be generous!\"" },
  { zh: "」帝從其志，封新安鄉侯。", literal: "\" The Emperor followed his wish and enfeoffed him as Marquis of Xin'an district.", idiomatic: "The Emperor followed his wish and enfeoffed him as Marquis of Xin'an district." },
  { zh: "帝使郎中魏郡馮勤典諸侯封事，勤差量功次輕重，國土遠近，地勢豐薄，不相逾越，莫不厭服焉。", literal: "The Emperor put Gentleman Feng Qin of Wei commandery in charge of the princes' enfeoffments; Qin differentiated merit ranking heavy and light, state lands near and far, and terrain rich or thin—none overstepping another—and none failed to be fully satisfied.", idiomatic: "The Emperor put Gentleman Feng Qin of Wei commandery in charge of enfeoffments for the princes; Qin weighed merit heavy and light, the distance of the fiefs, and whether the land was rich or poor—none overstepping another—and everyone was fully satisfied." },
  { zh: "帝以為能，尚書眾事皆令總錄之。", literal: "The Emperor considered him capable and ordered him to oversee and record all matters of the Masters of Writing.", idiomatic: "The Emperor considered him capable and ordered him to oversee and record all Masters of Writing business." },
  { zh: "故事：尚書郎以令史久次補之，帝始用孝廉為尚書郎。", literal: "By precedent: Masters of Writing Gentlemen were filled from clerks of long seniority; the Emperor for the first time used Filial and Incorrupt candidates as Masters of Writing Gentlemen.", idiomatic: "By precedent, Masters of Writing Gentlemen were drawn from long-serving clerks; the Emperor for the first time appointed Filial and Incorrupt candidates as Masters of Writing Gentlemen." },
  { zh: "5〔壬辰〕，起高廟于洛陽<ref>〔壬辰〕起高廟于洛陽考異曰：「帝紀『正月，壬子。", literal: "5 [day] renchen, erected the Gaozu temple in Luoyang <ref> On \"renchen, erected the Gaozu temple in Luoyang\" the Kaoyi note says: \"The Emperor's annals read 'First month, day renzi.", idiomatic: "5 On the day renchen, the Gaozu temple was erected in Luoyang. <ref> On \"renchen, erected the Gaozu temple in Luoyang,\" the Kaoyi note says: \"The Emperor's annals read 'In the first month, on the day renzi." },
  { zh: "』案正月甲子朔，不應有壬子，誤。", literal: "'\" Investigating: the first month's new moon is day jiazi—there should not be a renzi; this is an error.", idiomatic: "'\" Since the first day of the first month was jiazi, there should not have been a renzi; this is an error." },
  { zh: "」袁宏《後漢紀》(", literal: "\" Yuan Hong's Hou Han ji (", idiomatic: "\" Yuan Hong's Hou Han ji (" },
  { zh: "以下簡稱袁《紀》)", literal: "hereinafter abbreviated Yuan ji)", idiomatic: "hereinafter abbreviated as Yuan ji)" },
  { zh: "作「壬辰」，為正月廿九日，據補。", literal: "reads \"renchen,\" which is the twenty-ninth day of the first month—adopted here to correct.", idiomatic: "has \"renchen,\" the twenty-ninth day of the first month, which is adopted here as the correction." },
  { zh: "</ref>，四時合祀高祖、太宗、世宗；", literal: "</ref>, and at the four seasons jointly sacrificed to Gaozu, Taizong, and Shizong;", idiomatic: "</ref> At the four seasons Gaozu, Taizong, and Shizong were worshipped together;" },
  { zh: "建社稷于宗廟之右；", literal: "erected the altars of soil and grain to the right of the ancestral temple;", idiomatic: "the altars of soil and grain were built to the right of the ancestral temple;" },
  { zh: "立郊兆于城南。", literal: "and established the suburban precinct south of the city.", idiomatic: "and the suburban precinct was established south of the city." },
  { zh: "6長安城中糧盡，赤眉收載珍寶，大縱火燒宮室、市裡，恣行殺掠，長安城中無復人行；", literal: "6 Grain in Chang'an city was exhausted; the Red Eyebrows gathered and loaded treasures, greatly set fires burning palace halls and market wards, killed and plundered at will—no one walked in Chang'an any longer;", idiomatic: "6 Grain in Chang'an was exhausted; the Red Eyebrows loaded up treasures, set great fires in palace halls and market wards, and killed and plundered at will—no one walked the streets of Chang'an any longer;" },
  { zh: "乃引兵而西，眾號百萬，自南山轉掠城邑，遂入安定、北地。", literal: "they then led troops west, the masses claiming a million; turning from the Southern Mountains they plundered walled cities and entered Anding and Beidi.", idiomatic: "they then led troops west, their numbers claimed at a million; turning from the Southern Mountains they plundered walled cities and entered Anding and Beidi." },
  { zh: "鄧禹引兵南至長安，軍昆明池，謁祠高廟，收十一帝神主，送詣洛陽；", literal: "Deng Yu led troops south to Chang'an, encamped at Kunming Pool, visited and sacrificed at the Gaozu temple, gathered the spirit tablets of the eleven emperors, and sent them to Luoyang;", idiomatic: "Deng Yu led troops south to Chang'an, encamped at Kunming Pool, visited and sacrificed at the Gaozu temple, gathered the spirit tablets of the eleven emperors, and sent them to Luoyang;" },
  { zh: "因巡行園陵，為置吏士奉守焉。", literal: "and thereby toured the park tombs, setting officials and soldiers to maintain them.", idiomatic: "he then toured the park tombs and posted officials and soldiers to guard them." },
  { zh: "7真定王楊造讖記曰：「赤九之後，癭楊為主。", literal: "7 Prince of Zhending Yang forged a prophecy saying: \"After Red Nine, Goiter-Yang shall be lord.", idiomatic: "7 The Prince of Zhending, Yang, forged a prophecy saying, \"After Red Nine, Goiter-Yang shall be lord.\"" },
  { zh: "」楊病癭，欲以惑眾；", literal: "\" Yang suffered from goiter and wished thereby to delude the masses;", idiomatic: "Yang suffered from goiter and wished thereby to delude the masses;" },
  { zh: "與綿曼賊交通。", literal: "and he communicated with the Mianman bandits.", idiomatic: "and he communicated with the Mianman bandits." },
  { zh: "帝遣騎都尉陳副、游擊將軍鄧隆徵之，楊閉城門不內。", literal: "The Emperor dispatched Cavalry Commandant Chen Fu and Mobile Campaign General Deng Long to campaign against him; Yang shut the gates and would not admit them.", idiomatic: "The Emperor dispatched Cavalry Commandant Chen Fu and Mobile Campaign General Deng Long against him; Yang shut the gates and would not admit them." },
  { zh: "帝復遣前將軍耿純持節行幽、冀，所過勞慰王、侯，密敕收楊。", literal: "The Emperor again sent Forward General Geng Chun bearing credentials through You and Ji, along the way comforting kings and marquises, secretly ordering him to seize Yang.", idiomatic: "The Emperor again sent Forward General Geng Chun bearing credentials through You and Ji, comforting kings and marquises along the way while secretly ordering him to seize Yang." },
  { zh: "純至真定，止傳捨，邀楊相見。", literal: "Chun reached Zhending, stopped at the relay lodge, and invited Yang to meet.", idiomatic: "Chun reached Zhending, stopped at the relay lodge, and invited Yang to meet." },
  { zh: "純，真定宗室之出也，故楊不以為疑，且自恃眾強，而純意安靜，即從官屬詣之；", literal: "Chun was an offshoot of Zhending's imperial clan, so Yang did not suspect him; moreover he relied on his own numerous strength while Chun's intent seemed calm—Yang then went with his officials to him;", idiomatic: "Chun was of Zhending's imperial clan, so Yang did not suspect him; moreover he relied on his own strength while Chun seemed calm, and Yang went with his officials to see him;" },
  { zh: "楊兄弟並將輕兵在門外。", literal: "Yang's brothers all leading light troops were outside the gate.", idiomatic: "Yang's brothers, each leading light troops, waited outside the gate." },
  { zh: "楊入，見純，純接以禮敬，因延請其兄弟皆入，乃閉閣，悉誅之，因勒兵而出。", literal: "Yang entered and saw Chun; Chun received him with ritual courtesy, then extended invitation for his brothers all to enter; then shut the gate passage and executed them all, and thereby reined the troops out.", idiomatic: "Yang entered and saw Chun; Chun received him with courtesy, then invited his brothers in as well; he shut the gate passage, executed them all, and led his troops out." },
  { zh: "真定震怖，無敢動者。", literal: "Zhending was shaken in terror; none dared move.", idiomatic: "Zhending was shaken with terror; none dared stir." },
  { zh: "帝憐楊謀未發而誅，復封其子為真定王。", literal: "The Emperor pitied that Yang's plot had not erupted before he was executed, and again enfeoffed his son as Prince of Zhending.", idiomatic: "The Emperor pitied that Yang had been executed before his plot erupted, and again enfeoffed his son as Prince of Zhending." },
  { zh: "8二月，己酉，車駕幸修武。", literal: "8 Second month, day jiyou, the imperial carriage visited Xiuwu.", idiomatic: "8 In the second month, on the day jiyou, the imperial carriage visited Xiuwu." },
  { zh: "9鮑永、馮衍審知更始已亡，乃發喪，出儲大伯等，封上印綬，悉罷兵，幅巾詣河內，帝見永，問曰：「卿眾安在？", literal: "9 Bao Yong and Feng Yan had ascertained that Gengshi was already dead; they then held mourning, released Chu the Elder and others, sealed and submitted their seals and cords, disbanded all the army, came in headcloth to Henei; the Emperor saw Yong and asked: \"Where are your troops?", idiomatic: "9 Bao Yong and Feng Yan learned that Emperor Gengshi was already dead; they held mourning, released Chu the Elder and others, sealed and submitted their seals and cords, disbanded all their troops, and came to Henei in plain dress. The Emperor saw Yong and asked, \"Where are your troops?\"" },
  { zh: "」永離席叩頭曰：「臣事更始，不能令全，誠慚以其眾幸富貴，故悉罷之。", literal: "\" Yong left his mat, knocked his head, and said: \"Your servant served Gengshi and could not make him whole—I am truly ashamed to use his troops to seek fortune, and therefore disbanded them all.", idiomatic: "Yong left his mat, knocked his head, and said, \"I served Emperor Gengshi and could not preserve him—I would be ashamed to use his troops to seek fortune, and therefore disbanded them all.\"" },
  { zh: "」帝曰：「卿言大。", literal: "\" The Emperor said: \"Your words are great.", idiomatic: "The Emperor said, \"Your words are noble.\"" },
  { zh: "」而意不悅。", literal: "\" But his mind was not pleased.", idiomatic: "But he was not pleased." },
  { zh: "既而永以立功見用，衍遂廢棄。", literal: "Before long Yong was employed for establishing merit; Yan was then cast aside.", idiomatic: "Before long Yong was employed for his merit; Yan was then cast aside." },
  { zh: "永謂衍曰：「昔高祖賞季布之罪，誅丁固之功；", literal: "Yong said to Yan: \"In the past Gaozu pardoned Ji Bu's offense and executed Ding Gu's merit;", idiomatic: "Yong said to Yan, \"In the past Gaozu pardoned Ji Bu's offense and executed Ding Gu for his merit;" },
  { zh: "今遭明主，亦何憂哉！", literal: "now encountering a bright lord—what is there to worry about!", idiomatic: "now that we have met a bright lord, what is there to worry about!\"" },
  { zh: "」衍曰：「人有挑其鄰人之妻者，其長者罵而少者報之。", literal: "\" Yan said: \"There was a man who flirted with his neighbor's wife; the elder rebuked him while the younger repaid him.", idiomatic: "Yan said, \"A man flirted with his neighbor's wife; the elder rebuked him while the younger repaid her favors." },
  { zh: "後其夫死，取其長者。", literal: "Later when her husband died, she took the elder man.", idiomatic: "Later, when her husband died, she married the elder man." },
  { zh: "或謂之曰：『夫非罵爾者邪？", literal: "Someone said to her: 'Was not your husband the one who scolded you?", idiomatic: "Someone said to her, 'Was not your husband the one who scolded you?'" },
  { zh: "』曰：『在人欲其報我，在我欲其罵人也！", literal: "' She said: 'When I was another's, I wanted him to repay me; when I am mine, I wanted him to scold people!", idiomatic: "She said, 'When I was another man's wife I wanted him to repay me; as my own wife I wanted him to scold others!'" },
  { zh: "』夫天命難知，人道易守，守道之臣，何患死亡！", literal: "' Heaven's mandate is hard to know; the human Way is easy to keep—a minister who keeps the Way—what fear of death or ruin!", idiomatic: "Heaven's mandate is hard to know, but the human Way is easy to keep. For a minister who keeps the Way, what fear of death or ruin!\"" },
  { zh: "10大司空王梁屢違詔命，帝怒，遣尚書宗廣持節即軍中斬梁；", literal: "10 Grand Minister of Works Wang Liang repeatedly disobeyed imperial orders; the Emperor was angry and dispatched Master of Writing Zong Guang bearing credentials to behead Liang right in the army;", idiomatic: "10 Grand Minister of Works Wang Liang repeatedly disobeyed imperial orders; the Emperor was angry and dispatched Master of Writing Zong Guang bearing credentials to behead Liang in the army;" },
  { zh: "廣檻車送京師。", literal: "Guang sent him in a caged cart to the capital.", idiomatic: "Guang sent him to the capital in a caged cart." },
  { zh: "既至，赦之，以為中郎將，北守箕關。", literal: "When he arrived, the Emperor pardoned him and made him Palace Gentleman, guarding Jiguan Pass to the north.", idiomatic: "When he arrived, the Emperor pardoned him and made him Palace Gentleman, with him guarding Jiguan Pass to the north." },
  { zh: "11壬子，以太中大夫京兆宋弘為大司空。", literal: "11 Day renzi: he made Palace Counselor Song Hong of Jingzhao Grand Minister of Works.", idiomatic: "11 On the day renzi, Palace Counselor Song Hong of Jingzhao was made Grand Minister of Works." },
  { zh: "弘薦沛國桓譚，為議郎、給事中。", literal: "Hong recommended Huan Tan of Pei state, making him Counselor and Palace Attendant.", idiomatic: "Hong recommended Huan Tan of Pei and had him made Counselor and Palace Attendant." },
  { zh: "帝令譚鼓琴，愛其繁聲。", literal: "The Emperor ordered Tan to play the qin and loved his ornate tones.", idiomatic: "The Emperor had Tan play the qin and loved his ornate music." },
  { zh: "弘聞之，不悅；", literal: "Hong heard of this and was displeased;", idiomatic: "Hong heard of this and was displeased;" },
  { zh: "伺譚內出，正朝服坐府上，遣吏召之。", literal: "he waited until Tan had gone inside, put on correct court dress and sat in his office, and sent an official to summon him.", idiomatic: "he waited until Tan had gone inside, put on his court dress, sat in his office, and sent an official to summon him." },
  { zh: "譚至，不與席而讓之，且曰：「能自改邪，將令相舉以法乎？", literal: "Tan arrived; he gave him no mat but reproached him, saying: \"Can you reform yourself, or shall I have the chancellor report you by law?", idiomatic: "When Tan arrived, Hong gave him no seat but reproached him, saying, \"Will you reform yourself, or shall I have the chancellor report you by law?\"" },
  { zh: "」譚頓首辭謝；", literal: "\" Tan knocked his head and apologized;", idiomatic: "Tan knocked his head and apologized;" },
  { zh: "良久，乃遣之。", literal: "after a long while, then sent him away.", idiomatic: "only after a long while did he send him away." },
  { zh: "後大會群臣，帝使譚鼓琴。", literal: "Later at a great assembly of ministers the Emperor had Tan play the qin.", idiomatic: "Later, at a great assembly of ministers, the Emperor had Tan play the qin." },
  { zh: "譚見弘，失其常度。", literal: "Tan saw Hong and lost his usual pitch.", idiomatic: "Tan saw Hong and lost his usual pitch." },
  { zh: "帝怪而問之，弘乃離席免冠謝曰：「臣所以薦桓譚者，望能以忠正導主。", literal: "The Emperor wondered and asked; Hong then left his mat, removed his cap, and apologized: \"The reason your servant recommended Huan Tan was hoping he could guide the lord with loyalty and rectitude.", idiomatic: "The Emperor wondered and asked; Hong left his mat, removed his cap, and apologized, saying, \"I recommended Huan Tan hoping he could guide Your Majesty with loyalty and rectitude." },
  { zh: "而令朝廷耽悅鄭聲，臣之罪也。", literal: "Yet he has made the court indulge in wanton music—that is your servant's crime.", idiomatic: "Yet I have let the court indulge in wanton music—that is my crime.\"" },
  { zh: "」帝改容謝之。", literal: "\" The Emperor changed expression and apologized to him.", idiomatic: "The Emperor changed expression and apologized to him." },
  { zh: "湖陽公主新寡，帝與共論朝臣，微觀其意。", literal: "The Huyang princess was newly widowed; the Emperor discussed court ministers with her, subtly observing her intent.", idiomatic: "The Princess of Huyang was newly widowed; the Emperor discussed court ministers with her, subtly observing her intent." },
  { zh: "主曰：「宋公威容德器，群臣莫及。", literal: "The princess said: \"Lord Song's imposing bearing and moral capacity—no minister matches him.", idiomatic: "The princess said, \"Lord Song's imposing bearing and moral capacity—no minister matches him.\"" },
  { zh: "」帝曰：「方且圖之。", literal: "\" The Emperor said: \"I am just considering it.", idiomatic: "The Emperor said, \"I am just considering it.\"" },
  { zh: "」後弘被引見，帝令主坐屏風後，因謂弘曰：「諺言『貴易交，富易妻，』人情乎？", literal: "\" Later when Hong was summoned for audience the Emperor had the princess sit behind a screen and thereby said to Hong: \"The proverb says 'In nobility one changes friends; in wealth one changes wives'—is that human nature?", idiomatic: "Later, when Hong was summoned for audience, the Emperor had the princess sit behind a screen and said to Hong, \"The proverb says, 'In nobility one changes friends; in wealth one changes wives'—is that human nature?\"" },
  { zh: "」弘曰：「臣聞貧賤之知不可忘，糟糠之妻不下堂。", literal: "\" Hong said: \"Your servant has heard that friends from poverty and low estate must not be forgotten, and the wife who shared the chaff-gruel does not leave the hall.", idiomatic: "Hong said, \"I have heard that friends from poverty must not be forgotten, and the wife who shared the chaff-gruel does not leave the hall.\"" },
  { zh: "」帝顧謂主曰：「事不諧矣！", literal: "\" The Emperor turned and said to the princess: \"The affair will not work out!", idiomatic: "The Emperor turned and said to the princess, \"It will not work out!\"" },
  { zh: "12帝之討王郎也，彭寵發突騎以助軍，轉糧食，前後不絕，及帝追銅馬至薊，寵自負其功，意望甚高；", literal: "12 When the Emperor was attacking Wang Lang, Peng Chong dispatched shock cavalry to aid the army and transported grain without cease before and after; when the Emperor pursued the Bronze Horses to Ji, Chong relied on his merit and his expectations were very high;", idiomatic: "12 When the Emperor was attacking Wang Lang, Peng Chong sent shock cavalry to aid the army and transported grain without cease; when the Emperor pursued the Bronze Horses to Ji, Chong relied on his merit and his expectations were very high;" },
  { zh: "帝接之不能滿，以此懷不平。", literal: "the Emperor's reception could not satisfy him—on this account he harbored discontent.", idiomatic: "the Emperor's reception could not satisfy him, and on this account he harbored resentment." },
  { zh: "及即位，吳漢、王梁，寵之所遣，並為三公，而寵獨無所加，愈怏怏不得志，歎曰：「如此，我當為王。", literal: "When he took the throne Wu Han and Wang Liang—those Chong had sent—were both made Three Excellencies, while Chong alone received nothing added; he grew ever more discontent and ill at ease, sighing: \"Like this, I ought to be king.", idiomatic: "When he took the throne, Wu Han and Wang Liang—men Chong had sent—were both made Three Excellencies, while Chong alone received nothing; he grew ever more discontent and sighed, \"At this rate I ought to be king." },
  { zh: "但爾者，陛下忘我邪！", literal: "Only thus—has Your Majesty forgotten me!", idiomatic: "As it is, has Your Majesty forgotten me!\"" },
  { zh: "是時北州破散，而漁陽差完，有舊鐵官，寵轉以貿穀，積珍寶，益富強。", literal: "At this time the northern provinces were broken and scattered, while Yuyang was comparatively intact; it had an old iron office—Chong turned to trade grain, amassed treasures, and grew ever wealthier and stronger.", idiomatic: "At this time the northern provinces were broken and scattered, while Yuyang was comparatively intact; it had an old iron office, and Chong traded grain, amassed treasures, and grew ever wealthier and stronger." },
  { zh: "幽州牧朱浮，年少有俊才，欲厲風跡，收士心，辟召州中名宿及王莽時故吏二千石，皆引置幕府，多發諸郡倉穀稟贍其妻子。", literal: "Youzhou Regional Governor Zhu Fu, young and possessing outstanding talent, wished to sharpen conduct and reputation and win scholars' hearts; he summoned renowned elders of the province and former Mang-era officials at the two-thousand-bushel level, all placing them in his headquarters, and issued much from the various commanderies' granaries to provision their wives and children.", idiomatic: "Youzhou Regional Governor Zhu Fu, young and talented, wished to sharpen his reputation and win scholars' hearts; he summoned renowned elders of the province and former Wang Mang-era officials at the two-thousand-bushel level, placed them all in his headquarters, and drew heavily from commandery granaries to provision their wives and children." },
  { zh: "寵以為天下未定，師旅方起，不宜多置官屬以損軍實，不從其令。", literal: "Chong thought all under Heaven was not yet settled and armies were just rising—it was inappropriate to place many officials and thereby harm military substance; he did not obey his orders.", idiomatic: "Chong thought the realm was not yet settled and armies were just rising—it was inappropriate to place many officials and thereby drain military resources—and he did not obey Fu's orders." },
  { zh: "浮性矜急自多，寵亦狠強，嫌怨轉積。", literal: "Fu was by nature proud, hasty, and self-important; Chong was also fierce and strong—and mutual resentment accumulated.", idiomatic: "Fu was proud, hasty, and self-important; Chong was also fierce and strong, and their mutual resentment grew." },
  { zh: "浮數譖構之，密奏寵多聚兵穀，意計難量。", literal: "Fu repeatedly slandered and framed him, secretly memorializing that Chong had amassed much troops and grain and his intent was hard to measure.", idiomatic: "Fu repeatedly slandered him and secretly memorialized that Chong had amassed troops and grain and his intentions were hard to gauge." },
  { zh: "上輒漏泄令寵聞，以脅恐之。", literal: "The sovereign repeatedly leaked word for Chong to hear, to intimidate him.", idiomatic: "The sovereign repeatedly leaked word for Chong to hear, to intimidate him." },
  { zh: "至是，有詔徵寵，寵上疏，願與浮俱徵；", literal: "At this point there was an edict summoning Chong; Chong submitted a memorial wishing to be summoned together with Fu;", idiomatic: "At this point an edict summoned Chong; Chong submitted a memorial asking to be summoned together with Fu;" },
  { zh: "帝不許。", literal: "the Emperor did not permit it.", idiomatic: "the Emperor did not permit it." },
  { zh: "寵益以自疑。", literal: "Chong grew the more self-suspicious.", idiomatic: "Chong grew ever more suspicious." },
  { zh: "其妻素剛，不堪抑屈，固勸無受徵，曰：「天下未定，四方各自為雄。", literal: "His wife was by nature fierce, could not bear restraint, and firmly urged him not to accept the summons, saying: \"All under Heaven is not settled; the four quarters each make themselves hegemons.", idiomatic: "His wife was fierce by nature and could not bear restraint; she firmly urged him not to accept the summons, saying, \"The realm is not settled; each quarter has its own champion." },
  { zh: "漁陽大郡，兵馬最精，何故為人所奏，而棄此去乎！", literal: "Yuyang is a great commandery with the finest troops—why be reported by others and abandon this to go!", idiomatic: "Yuyang is a great commandery with the finest troops—why let yourself be reported on and abandon this place!\"" },
  { zh: "」寵又與所親信吏計議，皆懷怨於浮，莫有勸行者。", literal: "\" Chong again consulted trusted officials—all bore resentment toward Fu; none urged him to go.", idiomatic: "Chong again consulted trusted officials; all bore resentment toward Fu, and none urged him to go." },
  { zh: "帝遣寵從弟子後蘭卿喻之。", literal: "The Emperor sent Chong's younger clansman Hou Lanqing to instruct him.", idiomatic: "The Emperor sent Chong's younger clansman Hou Lanqing to instruct him." },
  { zh: "寵因留子後蘭卿，遂發兵反，拜署將帥，自將二萬餘人，攻朱浮於薊。", literal: "Chong thereupon detained Hou Lanqing's son, then raised troops in rebellion, appointed generals, himself leading more than twenty thousand men to attack Zhu Fu at Ji.", idiomatic: "Chong detained Hou Lanqing's son, then raised troops in rebellion, appointed generals, and himself led more than twenty thousand men to attack Zhu Fu at Ji." },
  { zh: "又以與耿況俱有重功，而恩賞並薄，數遣使〔要〕(", literal: "Moreover because he and Geng Kuang both had heavy merit yet favors and rewards were both thin, he repeatedly sent envoys to [summon] (", idiomatic: "Moreover, he and Geng Kuang had both rendered heavy service yet received thin rewards, and he repeatedly sent envoys to [summon] (" },
  { zh: "邀)", literal: "invite)", idiomatic: "invite)" },
  { zh: "誘況<ref>數遣使〔要〕(", literal: "entice Kuang <ref> On \"repeatedly sent envoys to [summon] (", idiomatic: "win over Kuang. <ref> On \"repeatedly sent envoys to [summon] (" },
  { zh: "邀)", literal: "invite)", idiomatic: "invite)" },
  { zh: "誘況章校「作『邀』者刻誤。", literal: "entice Kuang\" textual collation: \"Those reading 'invite' have a carving error.", idiomatic: "win over Kuang,\" textual collation: \"Those reading 'invite' have a carving error." },
  { zh: "十二行本正作『要』；", literal: "The twelve-line editions correctly read 'summon';", idiomatic: "The twelve-line editions correctly read 'summon';" },
  { zh: "乙十一行本同；", literal: "the Yi eleven-line edition the same;", idiomatic: "the Yi eleven-line edition agrees;" },
  { zh: "孔本同。", literal: "Kong's edition the same.", idiomatic: "Kong's edition agrees." },
  { zh: "」據改。", literal: "\" Corrected accordingly.", idiomatic: "\" Corrected accordingly." },
  { zh: "</ref>。", literal: "</ref>.", idiomatic: "</ref>" },
  { zh: "況不受，斬其使。", literal: "Kuang did not accept and beheaded his envoys.", idiomatic: "Kuang did not accept and beheaded his envoys." },
  { zh: "13延岑復反，圍南鄭。", literal: "13 Yan Cen rebelled again and besieged Nanzheng.", idiomatic: "13 Yan Cen rebelled again and besieged Nanzheng." },
  { zh: "漢中王嘉兵敗走。", literal: "Prince of Hanzhong Wang Jia's army was defeated and he fled.", idiomatic: "The Prince of Hanzhong, Wang Jia, was defeated and fled." },
  { zh: "岑遂據漢中，進兵武都；", literal: "Cen then held Hanzhong and advanced troops to Wudu;", idiomatic: "Cen then held Hanzhong and advanced into Wudu;" },
  { zh: "為更始柱功侯李寶所破，岑走天水。", literal: "he was broken by Gengshi's Pillar of Merit Marquis Li Bao; Cen fled to Tianshui.", idiomatic: "He was defeated by Emperor Gengshi's Pillar of Merit Marquis Li Bao; Cen fled to Tianshui." },
  { zh: "公孫述遣將侯丹取南鄭。", literal: "Gongsun Shu sent his general Hou Dan to take Nanzheng.", idiomatic: "Gongsun Shu sent his general Hou Dan to take Nanzheng." },
  { zh: "嘉收散卒得數萬人，以李寶為相，從武都南擊侯丹，不利，還軍河池、下辨，復與延岑連戰。", literal: "Jia gathered scattered soldiers obtaining several tens of thousands, made Li Bao chancellor, struck Hou Dan south from Wudu—fared ill, returned the army to Hechi and Xiabian, and fought Yan Cen again in succession.", idiomatic: "Jia gathered scattered troops to several tens of thousands, made Li Bao his chancellor, and struck Hou Dan south from Wudu; he fared ill, withdrew to Hechi and Xiabian, and fought Yan Cen again in succession." },
  { zh: "岑引北，入散關，至陳倉；", literal: "Cen drew north, entered Sans Pass, and reached Chencang;", idiomatic: "Cen withdrew north, entered Sans Pass, and reached Chencang;" },
  { zh: "嘉追擊，破之。", literal: "Jia pursued and attacked, routing them.", idiomatic: "Jia pursued and attacked, routing them." },
  { zh: "公孫述又遣將軍任滿從閬中下江州，東據扞關，於是盡有益州之地。", literal: "Gongsun Shu again sent General Ren Man down from Langzhong to Jiangzhou, seized Hanguan in the east, and thereby held all of Yizhou.", idiomatic: "Gongsun Shu again sent General Ren Man down from Langzhong to Jiangzhou, seized Hanguan in the east, and thereby held all of Yizhou." },
  { zh: "14辛卯<ref>丙戌二月甲午朔，無辛卯日。", literal: "14. On xinmao<ref>On bingxu, second month, jiawu as first day of the month—there is no xinmao day.", idiomatic: "14. On xinmao<ref>On bingxu year's second month, which began on jiawu, there was no xinmao day." },
  { zh: "范《書》同。", literal: "Fan's History agrees.", idiomatic: "The Book of the Later Han agrees." },
  { zh: "</ref>，上還洛陽。", literal: "</ref>, the emperor returned to Luoyang.", idiomatic: "</ref>, the emperor returned to Luoyang." },
  { zh: "15三月，乙〔酉〕(", literal: "15. Third month, yi [you] (", idiomatic: "15. Third month, yi [you] (" },
  { zh: "未)", literal: "wei)", idiomatic: "wei)" },
  { zh: "<ref>乙〔酉〕(", literal: "<ref>yi [you] (", idiomatic: "<ref>yi [you] (" },
  { zh: "未)", literal: "wei)", idiomatic: "wei)" },
  { zh: "三月癸亥朔，無乙未日，范《書》同。", literal: "Third month began on guihai; there was no yiwei day; Fan's History agrees.", idiomatic: "The third month began on guihai; there was no yiwei day; the Book of the Later Han agrees." },
  { zh: "袁《紀》作「乙酉」，查三月有乙酉日，為廿三日，據改。", literal: "Yuan Ji's Annals has \"yiyou\"; checking the third month there is a yiyou day, the twenty-third—emended accordingly.", idiomatic: "Yuan Ji's Annals has \"yiyou\"; checking the third month shows a yiyou day, the twenty-third—emended accordingly." },
  { zh: "</ref>，大赦。", literal: "</ref>, a general amnesty.", idiomatic: "</ref>, a general amnesty." },
  { zh: "16更始諸大將在南方未降者尚多。", literal: "16. Many of Gengshi's great generals in the south who had not yet submitted remained.", idiomatic: "16. Many of Gengshi's great generals in the south who had not yet submitted remained." },
  { zh: "帝召諸將議兵事，以檄叩地曰：「郾最強，宛為次，誰當擊之？", literal: "The emperor summoned the generals to discuss military affairs, struck the ground with a proclamation, and said: \"Yan is strongest, Wan is next—who shall attack them?", idiomatic: "The emperor summoned the generals to discuss military affairs, struck the ground with a proclamation, and said, \"Yan is strongest, Wan is next—who shall attack them?\"" },
  { zh: "」賈復率然對曰：「臣請擊郾。", literal: "\" Jia Fu impulsively replied: \"Your servant requests to attack Yan.", idiomatic: "\" Jia Fu impulsively replied, \"Your servant requests to attack Yan.\"" },
  { zh: "」帝笑曰：「執金吾擊郾，吾復何憂！", literal: "\" The emperor laughed and said: \"With the Bearer of the Mace attacking Yan, what have I to worry about!", idiomatic: "\" The emperor laughed and said, \"With the Bearer of the Mace attacking Yan, what have I to worry about!\"" },
  { zh: "大司馬當擊宛。", literal: "The Grand Marshal shall attack Wan.", idiomatic: "The Grand Marshal shall attack Wan.\"" },
  { zh: "」遂遣復擊郾，破之；", literal: "\" He thereupon sent Fu to attack Yan and routed them;", idiomatic: "He thereupon sent Jia Fu to attack Yan and routed them;" },
  { zh: "尹尊降。", literal: "Yin Zun surrendered.", idiomatic: "Yin Zun surrendered." },
  { zh: "又東擊更始淮陽太守暴汜，汜降。", literal: "He again attacked east against Gengshi's Administrator of Huaiyang Bao Si; Si surrendered.", idiomatic: "He again attacked east against Gengshi's Administrator of Huaiyang Bao Si; Bao Si surrendered." },
  { zh: "17夏，四月，虎牙大將軍蓋延督駙馬都尉馬武等四將軍擊劉永，破之；", literal: "17. Summer, fourth month, Tusked-Gate Great General Gai Yan supervised Escort-of-Steeds Commandant Ma Wu and four other generals in attacking Liu Yong and routed them;", idiomatic: "17. In summer, the fourth month, Tusked-Gate Great General Gai Yan supervised Escort-of-Steeds Commandant Ma Wu and four other generals in attacking Liu Yong and routed them;" },
  { zh: "遂圍永於睢陽。", literal: "they thereupon besieged Yong at Suiyang.", idiomatic: "they thereupon besieged Liu Yong at Suiyang." },
  { zh: "故更始將蘇茂反，殺淮陽太守潘蹇，據廣樂而臣於永；", literal: "Former Gengshi general Su Mao rebelled, killed Administrator of Huaiyang Pan Jian, held Guangle and submitted to Yong;", idiomatic: "Former Gengshi general Su Mao rebelled, killed Administrator of Huaiyang Pan Jian, held Guangle, and submitted to Liu Yong;" },
  { zh: "永以茂為大司馬、淮陽王。", literal: "Yong made Mao Grand Marshal and King of Huaiyang.", idiomatic: "Liu Yong made Su Mao Grand Marshal and King of Huaiyang." },
  { zh: "18吳漢擊宛，宛王賜奉更始妻子詣洛陽降；", literal: "18. Wu Han attacked Wan; King of Wan Liu Ci presented Gengshi's wife and children and came to Luoyang to surrender;", idiomatic: "18. Wu Han attacked Wan; King of Wan Liu Ci presented Gengshi's wife and children and came to Luoyang to surrender;" },
  { zh: "帝封賜為慎侯。", literal: "the emperor enfeoffed Ci as Marquis of Shen.", idiomatic: "the emperor enfeoffed Liu Ci as Marquis of Shen." },
  { zh: "叔父良、族父歙、族兄祉皆自長安來。", literal: "Paternal uncle Liang, clan uncle Xin, and clan elder brother Zhi all came from Chang'an.", idiomatic: "Paternal uncle Liu Liang, clan uncle Liu Xin, and clan elder brother Liu Zhi all came from Chang'an." },
  { zh: "甲午，封良為廣陽王，祉為城陽王；", literal: "On jiawu, he enfeoffed Liang as King of Guangyang and Zhi as King of Chengyang;", idiomatic: "On jiawu, he enfeoffed Liu Liang as King of Guangyang and Liu Zhi as King of Chengyang;" },
  { zh: "又封兄縯子章為太原王，興為魯王；", literal: "he also enfeoffed elder brother Yan's son Zhang as King of Taiyuan and Xing as King of Lu;", idiomatic: "he also enfeoffed elder brother Liu Yan's son Liu Zhang as King of Taiyuan and Liu Xing as King of Lu;" },
  { zh: "更始三子求、歆、鯉皆為列侯。", literal: "Gengshi's three sons Qiu, Xin, and Li were all made ranked marquises.", idiomatic: "Gengshi's three sons Liu Qiu, Liu Xin, and Liu Li were all made ranked marquises." },
  { zh: "19鄧王王常降，帝見之甚歡，曰：「吾見王廷尉，不憂南方矣！", literal: "19. Deng Prince Wang Chang submitted; the emperor was very pleased to see him and said: \"When I see Palace Commandant Wang, I need not worry about the south!", idiomatic: "19. Deng Prince Wang Chang submitted; the emperor was very pleased to see him and said, \"When I see Palace Commandant Wang, I need not worry about the south!\"" },
  { zh: "」拜為左曹，封山桑侯。", literal: "\" He appointed him Left Cao and enfeoffed him as Marquis of Shansang.", idiomatic: "He appointed him Left Cao and enfeoffed him as Marquis of Shansang." },
  { zh: "20五月，庚辰，封族父歙為泗水王。", literal: "20. Fifth month, gengchen, he enfeoffed clan uncle Xin as King of Sishui.", idiomatic: "20. In the fifth month, on gengchen, he enfeoffed clan uncle Liu Xin as King of Sishui." },
  { zh: "21帝以陰貴人雅性寬仁，欲立以為後。", literal: "21. The emperor, because Noble Consort Yin was by nature mild and generous, wished to make her empress.", idiomatic: "21. The emperor, because Noble Consort Yin was by nature mild and generous, wished to make her empress." },
  { zh: "貴人以郭貴人有子，終不肯當。", literal: "The noble lady, because Noble Consort Guo had a son, in the end would not accept the position.", idiomatic: "The noble lady, because Noble Consort Guo had a son, in the end would not accept the position." },
  { zh: "六月，戊戌，立貴人郭氏為皇后，以其子彊為皇太子；", literal: "Sixth month, wuxu, he established Noble Lady Guo as empress and made her son Qiang heir apparent;", idiomatic: "In the sixth month, on wuxu, he established Noble Lady Guo as empress and made her son Liu Qiang heir apparent;" },
  { zh: "大赦。", literal: "a general amnesty.", idiomatic: "a general amnesty." },
  { zh: "22丙午，封泗水王子終為淄川王。", literal: "22. On bingwu, he enfeoffed King of Sishui's son Zhong as King of Zichuan.", idiomatic: "22. On bingwu, he enfeoffed King of Sishui's son Liu Zhong as King of Zichuan." },
  { zh: "23秋，賈復南擊召陵、新息，平之。", literal: "23. Autumn, Jia Fu attacked south against Shaoling and Xixin and pacified them.", idiomatic: "23. In autumn, Jia Fu attacked south against Shaoling and Xixin and pacified them." },
  { zh: "後部將殺人於穎川，穎川太守寇恂捕得，繫獄。", literal: "A rear-department officer killed someone in Yingchuan; Administrator of Yingchuan Kou Xun captured him and imprisoned him.", idiomatic: "A rear-department officer killed someone in Yingchuan; Administrator of Yingchuan Kou Xun captured him and imprisoned him." },
  { zh: "時尚草創，軍營犯法，率多相容，恂戮之於市。", literal: "At the time the state was still being founded and army camps violated the law—mostly they tolerated one another; Xun executed him in the market.", idiomatic: "At the time the state was still being founded and army camps mostly tolerated one another's violations of the law; Kou Xun executed him in the market." },
  { zh: "復以為恥，還，過穎川，謂左右曰：「吾與寇恂並列將帥，而為其所陷，今見恂，必手劍之！", literal: "Fu took it as a shame; returning, he passed through Yingchuan and said to his attendants: \"I and Kou Xun are fellow commanders, yet he has trapped me—if I see Xun today I will surely run him through with my sword!", idiomatic: "Jia Fu took it as a disgrace; on his return he passed through Yingchuan and said to his attendants, \"Kou Xun and I are fellow commanders, yet he has trapped me—if I see Kou Xun today I will surely run him through with my sword!\"" },
  { zh: "」恂知其謀，不欲與相見。", literal: "\" Xun knew his plan and did not wish to meet him.", idiomatic: "Kou Xun knew his plan and did not wish to meet him." },
  { zh: "姊子谷崇曰：「崇，將也，得帶劍侍側。", literal: "His sister's son Gu Chong said: \"Chong is also a commander and may carry a sword at your side.", idiomatic: "His sister's son Gu Chong said, \"Chong is also a commander and may carry a sword at your side.\"" },
  { zh: "卒有變，足以相當。", literal: "If sudden trouble arises, I am enough to match him.", idiomatic: "If trouble arises suddenly, I am enough to match him.\"" },
  { zh: "」恂曰：「不然，昔藺相如不畏秦王而屈於廉頗者，為國也。", literal: "\" Xun said: \"That is not so; in antiquity Lin Xiangru did not fear the King of Qin yet yielded to Lian Po—for the sake of the state.", idiomatic: "Kou Xun said, \"That is not so; in antiquity Lin Xiangru did not fear the King of Qin yet yielded to Lian Po—for the sake of the state.\"" },
  { zh: "」乃敕屬縣盛供具，儲酒醪，執金吾軍入界，一人皆兼二人之饌。", literal: "\" He thereupon ordered the subordinate counties to prepare abundant supplies, store wine, and when the Bearer of the Mace's army entered the border, each man was served a feast for two.", idiomatic: "He thereupon ordered the subordinate counties to prepare abundant supplies, store wine, and when the Bearer of the Mace's army entered the border, each man was served a feast for two." },
  { zh: "恂出迎於道，稱疾而還。", literal: "Xun went out to meet him on the road, claimed illness, and returned.", idiomatic: "Kou Xun went out to meet him on the road, claimed illness, and returned." },
  { zh: "復勒兵欲追之，而吏士皆醉，遂過去。", literal: "Fu reined his troops wanting to pursue, but the officers and soldiers were all drunk, so he passed on.", idiomatic: "Jia Fu reined his troops wanting to pursue, but the officers and soldiers were all drunk, so he passed on." },
  { zh: "恂遣谷崇以狀聞，帝乃征恂。", literal: "Xun sent Gu Chong to report the situation; the emperor thereupon summoned Xun.", idiomatic: "Kou Xun sent Gu Chong to report the situation; the emperor thereupon summoned Kou Xun." },
  { zh: "恂至，引見；", literal: "When Xun arrived, he was granted audience;", idiomatic: "When Kou Xun arrived, he was granted audience;" },
  { zh: "時賈復先在坐，欲起相避。", literal: "at the time Jia Fu was already seated and wished to rise to avoid him.", idiomatic: "at the time Jia Fu was already seated and wished to rise to avoid him." },
  { zh: "帝曰：「天下未定，兩虎安得私鬥！", literal: "The emperor said: \"The realm is not yet settled—how can two tigers fight in private!", idiomatic: "The emperor said, \"The realm is not yet settled—how can two tigers fight in private!\"" },
  { zh: "今日朕分之。", literal: "Today I divide between you.", idiomatic: "Today I divide between you.\"" },
  { zh: "」於是並坐極歡，遂共車同出，結友而去。", literal: "\" Thereupon they sat together in greatest pleasure, then rode out in the same carriage, became friends, and departed.", idiomatic: "Thereupon they sat together in greatest pleasure, then rode out in the same carriage, became friends, and departed." },
  { zh: "24八月，帝自率諸將征五校。", literal: "24. Eighth month, the emperor himself led the generals in campaign against the Five Banners.", idiomatic: "24. In the eighth month, the emperor himself led the generals in campaign against the Five Banners." },
  { zh: "丙辰，幸內黃，大破五校於羛陽，降其眾五萬人。", literal: "On bingchen, he arrived at Neihuang and greatly routed the Five Banners at Yang, accepting the surrender of fifty thousand of their masses.", idiomatic: "On bingchen, he arrived at Neihuang and greatly routed the Five Banners at Yang, accepting the surrender of fifty thousand men." },
  { zh: "25帝遣游擊將軍鄧隆助朱浮討彭寵。", literal: "25. The emperor sent Mobile-Camp General Deng Long to assist Zhu Fu in attacking Peng Chong.", idiomatic: "25. The emperor sent Mobile-Camp General Deng Long to assist Zhu Fu in attacking Peng Chong." },
  { zh: "隆軍潞南，浮軍雍奴，遣吏奏狀。", literal: "Long's army at Lunan, Fu's army at Yongnu, they sent clerks to memorialize the situation.", idiomatic: "Deng Long's army was at Lunan and Zhu Fu's at Yongnu; they sent clerks to memorialize the situation." },
  { zh: "帝讀檄，怒，謂使吏曰：「營相去百里，其勢豈可得相及！", literal: "The emperor read the dispatch, was angry, and said to the envoy clerk: \"The camps are a hundred li apart—how could their forces possibly aid each other!", idiomatic: "The emperor read the dispatch, was angry, and said to the envoy clerk, \"The camps are a hundred li apart—how could their forces possibly aid each other!\"" },
  { zh: "比若還，北軍必敗矣。", literal: "By the time they return, the northern army is sure to be defeated.", idiomatic: "By the time they return, the northern army is sure to be defeated.\"" },
  { zh: "」彭寵果遣輕兵擊隆軍，大破之；", literal: "\" Peng Chong indeed sent light troops to strike Long's army and greatly defeated them;", idiomatic: "Peng Chong indeed sent light troops to strike Deng Long's army and routed them;" },
  { zh: "浮遠，遂不能救。", literal: "Fu was far away and could not rescue.", idiomatic: "Zhu Fu was far away and could not rescue." },
  { zh: "26蓋延圍睢陽數月，克之。", literal: "26. Gai Yan besieged Suiyang for several months and took it.", idiomatic: "26. Gai Yan besieged Suiyang for several months and took it." },
  { zh: "劉永走至虞，虞人反，殺其母、妻；", literal: "Liu Yong fled to Yu; the people of Yu rebelled and killed his mother and wife;", idiomatic: "Liu Yong fled to Yu; the people of Yu rebelled and killed his mother and wife;" },
  { zh: "永與麾下數十人奔譙。", literal: "Yong with several tens of his personal followers fled to Qiao.", idiomatic: "Liu Yong with several tens of his personal followers fled to Qiao." },
  { zh: "蘇茂、佼彊、周建合軍三萬餘人救永；", literal: "Su Mao, Jiao Qiang, and Zhou Jian united armies of more than thirty thousand to rescue Yong;", idiomatic: "Su Mao, Jiao Qiang, and Zhou Jian united armies of more than thirty thousand to rescue Liu Yong;" },
  { zh: "延與戰於沛西，大破之。", literal: "Yan battled them west of Pei and routed them greatly.", idiomatic: "Gai Yan battled them west of Pei and routed them greatly." },
  { zh: "永、彊、建走保湖陵，茂奔還廣樂；", literal: "Yong, Qiang, and Jian fled to hold Huling; Mao fled back to Guangle;", idiomatic: "Liu Yong, Jiao Qiang, and Zhou Jian fled to hold Huling; Su Mao fled back to Guangle;" },
  { zh: "延遂定沛、楚、臨淮。", literal: "Yan thereupon pacified Pei, Chu, and Linhuai.", idiomatic: "Gai Yan thereupon pacified Pei, Chu, and Linhuai." },
  { zh: "帝使太中大夫伏隆持節使青、徐二州，招降郡國。", literal: "The emperor sent Palace Counsellor Fu Long bearing credentials as envoy to Qing and Xu two provinces to summon and receive the surrender of commanderies and states.", idiomatic: "The emperor sent Palace Counsellor Fu Long bearing credentials as envoy to Qing and Xu to summon and receive the surrender of commanderies and states." },
  { zh: "青、徐群盜聞劉永破敗，皆惶怖請降。", literal: "Bandits in Qing and Xu, hearing Liu Yong was defeated, were all fearful and begged to submit.", idiomatic: "Bandits in Qing and Xu, hearing Liu Yong was defeated, were all fearful and begged to submit." },
  { zh: "張步遣其掾孫昱隨隆詣闕上書，獻鰒魚。", literal: "Zhang Bu sent his clerk Sun Yu to follow Long to the capital to present a memorial and offer preserved fish.", idiomatic: "Zhang Bu sent his clerk Sun Yu to follow Fu Long to the capital to present a memorial and offer preserved fish." },
  { zh: "隆，湛之子也。", literal: "Long was son of Zhan.", idiomatic: "Fu Long was the son of Fu Zhan." },
  { zh: "27堵鄉人董訢反宛城，執南陽太守劉驎。", literal: "27. Dong Xin of Duxiang rebelled at Wancheng and seized Administrator of Nanyang Liu Lin.", idiomatic: "27. Dong Xin of Duxiang rebelled at Wancheng and seized Administrator of Nanyang Liu Lin." },
  { zh: "揚化將軍堅鐔攻宛，拔之；", literal: "Exaltation General Jian Tan attacked Wan and took it;", idiomatic: "Exaltation General Jian Tan attacked Wan and took it;" },
  { zh: "訢走還堵鄉。", literal: "Xin fled back to Duxiang.", idiomatic: "Dong Xin fled back to Duxiang." },
  { zh: "28吳漢徇南陽諸縣，所過多侵暴。", literal: "28. Wu Han overrun Nanyang's various counties; wherever he passed he largely plundered violently.", idiomatic: "28. Wu Han overran Nanyang's various counties; wherever he passed he largely plundered violently." },
  { zh: "破虜將軍鄧奉謁歸新野，怒漢掠其鄉里，遂反，擊破漢軍，屯據淯陽，與諸賊合從。", literal: "Overthrow-the-Barbarians General Deng Feng paid a visit returning to Xinye, was angry that Han had raided his home district, thereupon rebelled, struck and routed Han's army, encamped at Yuyang, and joined in alliance with the various bandits.", idiomatic: "Overthrow-the-Barbarians General Deng Feng paid a visit returning to Xinye, was angry that Wu Han had raided his home district, thereupon rebelled, struck and routed Wu Han's army, encamped at Yuyang, and joined in alliance with the various bandits." },
  { zh: "29九月，壬戌，帝自內黃還。", literal: "29. Ninth month, renxu, the emperor returned from Neihuang.", idiomatic: "29. In the ninth month, on renxu, the emperor returned from Neihuang." },
  { zh: "30陝賊蘇況攻破弘農，帝使景丹討之。", literal: "30. Su Kuang the bandit of Shaan attacked and took Hongnong; the emperor sent Jing Dan to attack him.", idiomatic: "30. Su Kuang the bandit of Shaan attacked and took Hongnong; the emperor sent Jing Dan to attack him." },
  { zh: "會丹薨，征虜將軍祭遵擊弘農、柏華、蠻中賊，皆平之。", literal: "When Dan died, Campaign General Ji Zun attacked Hongnong, Baihua, and Manzhong bandits and pacified them all.", idiomatic: "When Jing Dan died, Campaign General Ji Zun attacked the Hongnong, Baihua, and Manzhong bandits and pacified them all." },
  { zh: "31赤眉引兵欲西上隴，隗囂遣將軍楊廣迎擊，破之；", literal: "31. The Red Eyebrows led troops wishing to go west up the Long Road; Wei Ao sent General Yang Guang to meet and attack and routed them;", idiomatic: "31. The Red Eyebrows led troops wishing to go west up the Long Road; Wei Ao sent General Yang Guang to meet and attack and routed them;" },
  { zh: "又追敗之於烏氏、涇陽間。", literal: "he again pursued and defeated them between Wushi and Jingyang.", idiomatic: "he again pursued and defeated them between Wushi and Jingyang." },
  { zh: "赤眉至陽城番須中，逢大雪，坑谷皆滿，士多凍死。", literal: "The Red Eyebrows reached Yangcheng in the Fanxu region; they met great snow, gullies and ravines were all full, and many soldiers froze to death.", idiomatic: "The Red Eyebrows reached Yangcheng in the Fanxu region; they met great snow, gullies and ravines were all full, and many soldiers froze to death." },
  { zh: "乃復還，發掘諸陵，取其寶貨。", literal: "They thereupon returned again, dug open the various tombs, and took their treasures.", idiomatic: "They thereupon returned again, dug open the various tombs, and took their treasures." },
  { zh: "凡有玉匣殮者，率皆如生，賊遂污辱呂后尸。", literal: "Wherever there were jade casket burials, all were as if alive; the bandits thereupon violated and shamed Empress Lü's corpse.", idiomatic: "Wherever there were jade-casket burials, the corpses were all as if alive; the bandits thereupon violated and shamed Empress Lü's corpse." },
  { zh: "鄧禹遣兵擊之於郁夷，反為所敗。", literal: "Deng Yu sent troops to strike them at Yuyi and in turn was defeated by them.", idiomatic: "Deng Yu sent troops to strike them at Yuyi and in turn was defeated by them." },
  { zh: "禹乃出之雲陽。", literal: "Yu thereupon withdrew to Yunyang.", idiomatic: "Deng Yu thereupon withdrew to Yunyang." },
  { zh: "赤眉復入長安。", literal: "The Red Eyebrows again entered Chang'an.", idiomatic: "The Red Eyebrows again entered Chang'an." },
  { zh: "延岑屯杜陵，赤眉將逢安擊之。", literal: "Yan Cen encamped at Duling; Red Eyebrows' general Feng An attacked him.", idiomatic: "Yan Cen encamped at Duling; Red Eyebrows' general Feng An attacked him." },
  { zh: "鄧禹以安精兵在外，引兵襲長安；", literal: "Deng Yu, because An's crack troops were abroad, led troops to raid Chang'an;", idiomatic: "Deng Yu, because Feng An's crack troops were abroad, led troops to raid Chang'an;" },
  { zh: "會謝祿救至，禹兵敗走。", literal: "when Xie Lu's rescue arrived, Yu's army was defeated and fled.", idiomatic: "when Xie Lu's rescue arrived, Deng Yu's army was defeated and fled." },
  { zh: "延岑擊逢安，大破之，死者十餘萬人。", literal: "Yan Cen attacked Feng An and routed him greatly; more than a hundred thousand died.", idiomatic: "Yan Cen attacked Feng An and routed him greatly; more than a hundred thousand died." },
  { zh: "廖湛將赤眉十八萬攻漢中王嘉；", literal: "Liao Zhan led one hundred eighty thousand Red Eyebrows to attack King of Hanzhong Wang Jia;", idiomatic: "Liao Zhan led one hundred eighty thousand Red Eyebrows to attack King of Hanzhong Wang Jia;" },
  { zh: "嘉與戰於谷口，大破之，嘉手殺湛，遂到雲陽就穀。", literal: "Jia battled them at Gukou, routed them greatly; Jia personally killed Zhan, then went to Yunyang to obtain grain.", idiomatic: "Wang Jia battled them at Gukou and routed them greatly; Jia personally killed Liao Zhan, then went to Yunyang to obtain grain." },
  { zh: "嘉妻兄新野來歙，帝之姑子也。", literal: "Jia's wife's elder brother Laixi Lai Xin was the emperor's cousin by marriage.", idiomatic: "Wang Jia's wife's elder brother Laixi Lai Xin was the emperor's cousin by marriage." },
  { zh: "帝令鄧禹招嘉，嘉因歙詣禹降。", literal: "The emperor ordered Deng Yu to summon Jia; Jia through Xin went to Yu and submitted.", idiomatic: "The emperor ordered Deng Yu to summon Wang Jia; Jia through Lai Xin went to Yu and submitted." },
  { zh: "李寶倨慢，禹斬之。", literal: "Li Bao was arrogant and rude; Yu beheaded him.", idiomatic: "Li Bao was arrogant and rude; Deng Yu beheaded him." },
  { zh: "32冬，十一月，以廷尉岑彭為征南大將軍。", literal: "32. Winter, eleventh month, the emperor made Censor-in-Chief Cen Peng Campaign-in-the-South Great General.", idiomatic: "32. In winter, the eleventh month, the emperor made Censor-in-Chief Cen Peng Campaign-in-the-South Great General." },
  { zh: "帝於大會中指王常謂群臣曰：「此家率下江諸將輔翼漢室，心如金石，真忠臣也！", literal: "At a great assembly the Emperor pointed at Wang Chang and said to the assembled ministers: \"This family led the generals of the lower Yangtze in assisting the Han house; their hearts are like metal and stone—a true loyal minister!", idiomatic: "At a great assembly the Emperor pointed at Wang Chang and said to the ministers, \"This family led the generals of the lower Yangtze in assisting the Han house; their hearts are like metal and stone—a true loyal minister!\"" },
  { zh: "」即日，拜常為漢忠將軍，使與岑彭率建義大將軍朱祜等七將軍討鄧奉、董訢。", literal: "\" That same day he appointed Chang as Loyal-to-Han General and ordered him together with Cen Peng to lead Establish-the-Righteousness Grand General Zhu Hu and seven other generals to attack Deng Feng and Dong Xin.", idiomatic: "That same day he appointed Wang Chang Loyal-to-Han General and ordered him, with Cen Peng, to lead Establish-the-Righteousness Grand General Zhu Hu and seven other generals against Deng Feng and Dong Xin." },
  { zh: "彭等先擊堵鄉，鄧奉救之。", literal: "Peng and the others first attacked Du village; Deng Feng came to its relief.", idiomatic: "Peng and the others first attacked Du village; Deng Feng marched to relieve it." },
  { zh: "朱祜軍敗，為奉所獲。", literal: "Zhu Hu's army was defeated and he was captured by Feng.", idiomatic: "Zhu Hu's army was defeated and he was captured by Deng Feng." },
  { zh: "33銅馬、青犢、尤來餘賊共立孫登為天子。", literal: "33 The remnant bandits of Bronze Horse, Green Calf, and Youlai jointly set up Sun Deng as Son of Heaven.", idiomatic: "33 The remnant bandits of Bronze Horse, Green Calf, and Youlai jointly made Sun Deng Son of Heaven." },
  { zh: "登將樂玄殺登，以其眾五萬餘人降。", literal: "Deng's general Yue Xuan killed Deng and surrendered with his masses of more than fifty thousand.", idiomatic: "Sun Deng's general Yue Xuan killed him and surrendered with more than fifty thousand men." },
  { zh: "34鄧禹自馮愔叛後，威名稍損，又乏糧食，戰數不利，歸附者日益離散。", literal: "34 After Deng Yu, since Feng Yin's rebellion, his prestige was somewhat diminished; he also lacked food; battles were repeatedly unfavorable; and those who had submitted daily dispersed.", idiomatic: "34 After Feng Yin's rebellion, Deng Yu's prestige had faded somewhat; he also lacked provisions, battles went badly again and again, and those who had submitted drifted away day by day." },
  { zh: "赤眉、延岑暴亂三輔，郡縣大姓各擁兵眾，禹不能定。", literal: "The Red Eyebrows and Yan Cen ravaged the Three Metropolises; great clans of commanderies and counties each held troops and masses—Yu could not pacify them.", idiomatic: "The Red Eyebrows and Yan Cen ravaged the Three Metropolises; great clans in every commandery and county held private armies, and Yu could not pacify the region." },
  { zh: "帝乃遣偏將軍馮異代禹討之，車駕送至河南，敕異曰：「三輔遭王莽、更始之亂，重以赤眉、延岑之醜，元元塗炭，無所依訴。", literal: "The Emperor then sent Lieutenant General Feng Yi to replace Yu in attacking them; the imperial carriage escorted him to Henan and charged Yi, saying: \"The Three Metropolises have suffered the disorders of Wang Mang and Gengshi, compounded by the atrocities of the Red Eyebrows and Yan Cen; the common folk are smeared with charcoal and have nowhere to appeal.", idiomatic: "The Emperor then sent Lieutenant General Feng Yi to replace Yu and campaign against them; the imperial carriage escorted him to Henan, where he charged Yi, \"The Three Metropolises have suffered the disorders of Wang Mang and Gengshi, compounded by the atrocities of the Red Eyebrows and Yan Cen; the people are in ashes and have nowhere to turn.\"" },
  { zh: "將軍今奉辭討諸不軌，營〔堡〕(", literal: "General, you now receive orders to campaign against the lawless; fortified camps [堡](", idiomatic: "General, you now receive orders to campaign against the lawless; fortified camps [堡](" },
  { zh: "保)", literal: "protect)", idiomatic: "protect)" },
  { zh: "降者<ref>營〔堡〕(", literal: "those who surrender<ref>fortified camps [堡](", idiomatic: "those who surrender<ref>fortified camps [堡](" },
  { zh: "保)", literal: "protect)", idiomatic: "protect)" },
  { zh: "降者章校「十二行本『保』作『堡』；", literal: "those who surrender—Zhang's collation: the twelve-line edition reads \"fortress\" for \"protect\";", idiomatic: "those who surrender—collation: the twelve-line edition reads \"fortress\" for \"protect\";" },
  { zh: "乙十一行本同；", literal: "the Yi eleven-line edition agrees;", idiomatic: "the Yi eleven-line edition agrees;" },
  { zh: "孔本同；", literal: "Kong's edition agrees;", idiomatic: "Kong's edition agrees;" },
  { zh: "張校同。", literal: "Zhang's collation agrees.", idiomatic: "Zhang's collation agrees." },
  { zh: "」據改。", literal: "\" Emended on this authority.", idiomatic: "Emended accordingly." },
  { zh: "</ref>，遣其渠帥詣京師；", literal: "</ref>, send their chieftains to the capital;", idiomatic: "</ref>, send their chieftains to the capital;" },
  { zh: "散其小民，令就農桑；", literal: "disperse their common people and have them return to farming and sericulture;", idiomatic: "disperse the common people and have them return to farming;" },
  { zh: "壞其營壁，無使復聚。", literal: "destroy their fortified camps and do not let them gather again.", idiomatic: "tear down their fortified camps and do not let them gather again." },
  { zh: "征伐非必略地、屠城，要在平定安集之耳。", literal: "Campaigning need not necessarily seize territory and slaughter cities—the essential is only to pacify and settle the people.", idiomatic: "Campaigning need not seize territory and slaughter cities—the point is only to pacify and settle the people." },
  { zh: "諸將非不健鬥，然好虜掠。", literal: "The generals are not unable to fight fiercely, yet they love plundering.", idiomatic: "The generals are not unable to fight, yet they love to plunder." },
  { zh: "卿本能御吏士，念自修敕，無為郡縣所苦！", literal: "You by nature can control officers and soldiers—mind to discipline yourself and do not cause suffering to commanderies and counties!", idiomatic: "You by nature can control officers and soldiers—mind to discipline yourself and do not afflict the commanderies and counties!\"" },
  { zh: "」異頓首受命，引而西，所至布威信，群盜多降。", literal: "\" Feng Yi bowed his head, accepted the command, led forces westward; wherever he went he spread authority and trust, and many bandits surrendered.", idiomatic: "Feng Yi bowed, accepted the charge, and led his army west; wherever he went he spread authority and trust, and many bandits surrendered." },
  { zh: "臣光曰：昔周人頌武王之德曰：「舖時繹思，我徂惟求定。", literal: "Your servant Guang says: Formerly the people of Zhou praised King Wu's virtue, saying: \"Spread the time and prolong the thought; our going forth seeks only stability.", idiomatic: "Sima Guang remarks: Formerly the Zhou praised King Wu's virtue, saying, \"Profound was his thoughtful care; our going forth sought only stability.\"" },
  { zh: "」言王者之兵志，在布陳威德安民而已。", literal: "\" This states that the kingly army's aim is only to spread and display authority and virtue to settle the people.", idiomatic: "This means that the kingly army's aim is only to spread authority and virtue and settle the people." },
  { zh: "觀光武之所以取關中，用是道也。", literal: "Observing how Guangwu took Guanzhong, he used this Way.", idiomatic: "Seeing how Guangwu took Guanzhong, he used this same Way." },
  { zh: "豈不美哉！", literal: "Is it not beautiful!", idiomatic: "Is it not admirable!" },
  { zh: "35又詔徵鄧禹還，曰：「慎毋與窮寇爭鋒！", literal: "35 Again he issued an edict summoning Deng Yu back, saying: \"Take care not to contend with a cornered foe!", idiomatic: "35 The Emperor again issued an edict summoning Deng Yu back, saying, \"Take care not to fight a cornered foe!\"" },
  { zh: "赤眉無穀，自當來東。", literal: "The Red Eyebrows have no grain—they will naturally come east.", idiomatic: "The Red Eyebrows have no grain—they will come east on their own." },
  { zh: "吾以飽待饑，以逸待勞，折棰笞之，非諸將憂也。", literal: "We with full stomachs await the hungry, with ease await the weary—a broken whip will chastise them; this is not a worry for the generals.", idiomatic: "We with full bellies await the hungry, with ease await the weary—a broken whip will flog them—this is no worry for the generals." },
  { zh: "無得復妄進兵！", literal: "Do not rashly advance troops again!", idiomatic: "Do not rashly advance troops again!\"" },
  { zh: "帝以伏隆為光祿大夫，復使於張步，拜步東萊太守，并與新除青州牧、守、都尉俱東。", literal: "The Emperor made Fu Long Grand Master of Splendor and again sent him to Zhang Bu, appointing Bu Administrator of Donglai, and together with the newly appointed Governor of Qing Province, administrators, and commandants he went east together.", idiomatic: "The Emperor made Fu Long Grand Master of Splendor and again sent him to Zhang Bu, appointing Bu Administrator of Donglai; together with the newly appointed governor of Qing Province and the administrators and commandants, they all went east." },
  { zh: "詔隆輒拜令、長以下。", literal: "An edict ordered Long to appoint on the spot magistrates, chiefs, and those below.", idiomatic: "An edict authorized Long to appoint magistrates, chiefs, and subordinates on the spot." },
  { zh: "36十二月，戊午，詔宗室列侯為王莽所絕者，皆復故國。", literal: "36 In the twelfth month, on wuwu day, an edict: among collateral princes and marquises whose lines were extinguished by Wang Mang, all were restored to their former states.", idiomatic: "36 In the twelfth month, on wuwu day, an edict restored to their former states all collateral princes and marquises whose lines Wang Mang had extinguished." },
  { zh: "37三輔大饑，人相食，城郭皆空，白骨蔽野，遺民往往聚為營堡，各堅壁清野。", literal: "37 The Three Metropolises suffered great famine; people ate one another; cities and ramparts were all empty; white bones covered the wilderness; surviving people often gathered into fortified camps, each securing walls and clearing the countryside.", idiomatic: "37 The Three Metropolises suffered terrible famine; people ate one another; cities and towns stood empty; white bones covered the fields; survivors often gathered into fortified camps, each walling up and clearing the countryside." },
  { zh: "赤眉虜掠無所得，乃引而東歸，眾尚二十餘萬，隨道復散。", literal: "The Red Eyebrows plundered but obtained nothing; they then led forces east in retreat—masses still more than two hundred thousand, scattering again along the road.", idiomatic: "The Red Eyebrows raided but gained nothing; they then marched east in retreat, still more than two hundred thousand strong, scattering again along the way." },
  { zh: "帝遣破奸將軍侯進等屯新安，建威大將軍耿弇等屯宜陽，以要其還路，敕諸將曰：「賊若東走，可引宜陽兵會新安；", literal: "The Emperor sent Smash-Treason General Hou Jin and others to hold Xinan, Established-Power Grand General Geng Yin and others to hold Yiyang, to intercept their return route, charging the generals: \"If the bandits flee east, you may draw the Yiyang troops to join at Xinan;", idiomatic: "The Emperor sent Smash-Treason General Hou Jin and others to hold Xinan and Established-Power Grand General Geng Yin and others to hold Yiyang, to block their return route, and charged the generals, \"If the bandits flee east, draw the Yiyang troops to join at Xinan;\"" },
  { zh: "賊若南走，可引新安兵會宜陽。", literal: "if the bandits flee south, you may draw the Xinan troops to join at Yiyang.", idiomatic: "if they flee south, draw the Xinan troops to join at Yiyang.\"" },
  { zh: "」馮異與赤眉遇於華陰，相拒六十餘日，戰數十合，降其將卒五千餘人。", literal: "\" Feng Yi encountered the Red Eyebrows at Huayin; they faced each other for more than sixty days; fought several tens of engagements; and reduced their generals and soldiers by more than five thousand who surrendered.", idiomatic: "Feng Yi met the Red Eyebrows at Huayin; they faced each other for more than sixty days, fought several dozen engagements, and induced more than five thousand of their officers and men to surrender." },
  { zh: "<divclass=\"references-small\"><references/></div>", literal: "<divclass=\"references-small\"><references/></div>", idiomatic: "<divclass=\"references-small\"><references/></div>" },
  { zh: "category:資治通鑑", literal: "—", idiomatic: "—" }
];
